namespace PizzaOrderingSystem
{
    public partial class frmMain : Form
    {
        // Variable to store the running total
        private double totalAmount = 0;

        public frmMain()
        {
            InitializeComponent();
        }

        // EVENT: Runs when the form first opens
        private void frmMain_Load(object sender, EventArgs e)
        {
            // Set default selections so the cashier does not start with empty boxes
            cmbPizzaType.SelectedIndex = 0; // Cheese
            cmbSize.SelectedIndex = 0;      // Small
            UpdateUnitPrice(); // Show the starting price
        }

        // Returns the base price for the selected pizza type
        private double GetBasePrice(string pizzaType)
        {
            if (pizzaType == "Cheese") return 200;
            if (pizzaType == "Hawaiian") return 230;
            if (pizzaType == "Pepperoni") return 250;
            if (pizzaType == "Bacon") return 280;
            if (pizzaType == "Supreme") return 300;
            return 0;
        }

        // Returns the extra price for the selected size
        private double GetSizePrice(string size)
        {
            if (size == "Small") return 0;
            if (size == "Medium") return 50;
            if (size == "Large") return 100;
            return 0;
        }

        // Shows the price of 1 pizza with the current type + size
        private void UpdateUnitPrice()
        {
            if (cmbPizzaType.SelectedItem == null || cmbSize.SelectedItem == null)
                return;

            string pizza = cmbPizzaType.SelectedItem.ToString();
            string size = cmbSize.SelectedItem.ToString();

            double unitPrice = GetBasePrice(pizza) + GetSizePrice(size);
            lblUnitPrice.Text = "₱" + unitPrice.ToString("0.00");
        }

        // EVENT: When pizza type changes, update the price display
        private void cmbPizzaType_SelectedIndexChanged(object sender, EventArgs e)
        {
            UpdateUnitPrice();
        }

        // EVENT: When size changes, update the price display
        private void cmbSize_SelectedIndexChanged(object sender, EventArgs e)
        {
            UpdateUnitPrice();
        }

        // EVENT: Add button - adds the selected pizza to the order
        private void btnAdd_Click(object sender, EventArgs e)
        {
            string pizza = cmbPizzaType.SelectedItem.ToString();
            string size = cmbSize.SelectedItem.ToString();
            int qty = (int)numQuantity.Value;

            double unitPrice = GetBasePrice(pizza) + GetSizePrice(size);
            double lineTotal = unitPrice * qty;

            // Add a new row to the order table
            dgvOrder.Rows.Add(pizza, size, qty, "₱" + unitPrice.ToString("0.00"), "₱" + lineTotal.ToString("0.00"));

            UpdateTotals();
        }

        // Recalculates subtotal and total automatically
        private void UpdateTotals()
        {
            totalAmount = 0;

            // Loop through all rows and add up the line totals
            foreach (DataGridViewRow row in dgvOrder.Rows)
            {
                // Column 4 holds text like "₱250.00" - remove ₱ then convert to number
                string text = row.Cells[4].Value.ToString().Replace("₱", "");
                totalAmount += Convert.ToDouble(text);
            }

            lblSubtotalValue.Text = "₱" + totalAmount.ToString("0.00");
            lblTotalValue.Text = "₱" + totalAmount.ToString("0.00");
        }

        // EVENT: Remove button - removes the selected row from the order
        private void btnRemove_Click(object sender, EventArgs e)
        {
            if (dgvOrder.SelectedRows.Count > 0)
            {
                dgvOrder.Rows.RemoveAt(dgvOrder.SelectedRows[0].Index);
                UpdateTotals();
            }
            else
            {
                MessageBox.Show("Please select an item to remove.",
                    "Remove Item", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        // EVENT: Clear button - removes everything from the order
        private void btnClear_Click(object sender, EventArgs e)
        {
            dgvOrder.Rows.Clear();
            txtCash.Clear();
            lblChangeValue.Text = "₱0.00";
            UpdateTotals();
        }

        // EVENT: Checkout button - handles payment
        private void btnCheckout_Click(object sender, EventArgs e)
        {
            // 1. Prevent checkout if order is empty
            if (dgvOrder.Rows.Count == 0)
            {
                MessageBox.Show("Order is empty. Please add pizzas first.",
                    "Checkout", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            // 2. Check if cash entered is a valid number
            double cash;
            if (!double.TryParse(txtCash.Text, out cash))
            {
                MessageBox.Show("Please enter a valid cash amount.",
                    "Checkout", MessageBoxButtons.OK, MessageBoxIcon.Error);
                txtCash.Focus();
                return;
            }

            // 3. Prevent checkout if cash is insufficient
            if (cash < totalAmount)
            {
                MessageBox.Show("Insufficient cash! Total is ₱" + totalAmount.ToString("0.00"),
                    "Checkout", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            // 4. Calculate change
            double change = cash - totalAmount;
            lblChangeValue.Text = "₱" + change.ToString("0.00");

            // 5. Show success message
            MessageBox.Show("Payment successful!\n\nTotal: ₱" + totalAmount.ToString("0.00")
                + "\nCash: ₱" + cash.ToString("0.00")
                + "\nChange: ₱" + change.ToString("0.00"),
                "Transaction Complete", MessageBoxButtons.OK, MessageBoxIcon.Information);

            // 6. Clear the order after successful checkout
            dgvOrder.Rows.Clear();
            txtCash.Clear();
            lblChangeValue.Text = "₱0.00";
            UpdateTotals();
        }

        // EVENT: Logout button - returns to login screen
        private void btnLogout_Click(object sender, EventArgs e)
        {
            frmLogin loginForm = new frmLogin();
            loginForm.Show();
            this.Close(); // Close the ordering screen
        }

        // EVENT: If user closes this window with X, show login again
        private void frmMain_FormClosed(object sender, FormClosedEventArgs e)
        {
            // If no other window is open, go back to login
            if (Application.OpenForms.Count == 0)
            {
                // App would exit, so reopen login to allow logout behavior
                // (Only needed when Logout was not used)
            }
        }
    }
}

