namespace PizzaOrderingSystem
{
    public partial class frmLogin : Form
    {
        public frmLogin()
        {
            InitializeComponent();
        }

        // EVENT 1: Login button click
        private void btnLogin_Click(object sender, EventArgs e)
        {
            // Check username and password
            if (txtUsername.Text == "cashier" && txtPassword.Text == "1234")
            {
                // Correct! Open the ordering system
                frmMain mainForm = new frmMain();
                mainForm.Show();
                this.Hide(); // Hide login screen (do not close, so app keeps running)
            }
            else
            {
                // Wrong credentials - show error message
                MessageBox.Show("Invalid username or password.\nPlease try again.",
                    "Login Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                txtPassword.Clear();
                txtUsername.Focus();
            }
        }

        // EVENT 2: Exit button click
        private void btnExit_Click(object sender, EventArgs e)
        {
            Application.Exit();
        }

        // EVENT 3: Press Enter in password box to login
        private void txtPassword_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                btnLogin_Click(sender, e);
            }
        }
    }
}

