    }).format(date);
  };

  GLAZE.formatLongDate = function (dateLike) {
    const date = new Date(dateLike);
    return new Intl.DateTimeFormat('en-PH', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
    }).format(date);
  };

  GLAZE.formatDateTime = function (dateLike) {
    return GLAZE.formatShortDate(dateLike) + ' · ' + GLAZE.formatTime(dateLike);
  };

  GLAZE.timeAgo = function (dateLike) {
    const diff = Date.now() - new Date(dateLike).getTime();
    const minutes = Math.max(0, Math.floor(diff / 60000));
    if (minutes < 1) return 'just now';
    if (minutes < 60) return minutes + ' min ago';
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return hours + (hours === 1 ? ' hr ago' : ' hrs ago');
    const days = Math.floor(hours / 24);
    if (days < 7) return days + (days === 1 ? ' day ago' : ' days ago');
    return GLAZE.formatShortDate(dateLike);
  };

  GLAZE.startOfToday = function () {
    const date = new Date();
    date.setHours(0, 0, 0, 0);
    return date;
  };

  GLAZE.isToday = function (dateLike) {
    return new Date(dateLike) >= GLAZE.startOfToday();
  };

  GLAZE.yesterdayStart = function () {
    const date = GLAZE.startOfToday();
    date.setDate(date.getDate() - 1);
    return date;
  };

  GLAZE.todayInputValue = function () {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day;
  };

  GLAZE.initials = function (name) {
    return String(name || '')
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map(function (part) {
        return part.charAt(0).toUpperCase();
      })
      .join('');
  };

  GLAZE.plural = function (number, singular, plural) {
    return Number(number) === 1 ? singular : plural || singular + 's';
  };
})();

(function () {
  const GLAZE = (window.GLAZE = window.GLAZE || {});
  let uid = 0;

  function seededNumbers(seed, count) {
    let value = seed * 7919 + 17;
    const out = [];
    for (let i = 0; i < count; i += 1) {
      value = (value * 9301 + 49297) % 233280;
      out.push(value / 233280);
    }
    return out;
  }

  function toppingsFor(donut, seed, uidSuffix) {
    const colors = donut.toppingColors || ['#FFF8E8'];
    const randoms = seededNumbers(seed + 5, 60);
    let output = '';

    const point = function (index, radiusMin, radiusMax) {
      const angle = (index * 137.5 + randoms[index] * 33 + 9) * (Math.PI / 180);
      const radius = radiusMin + randoms[index + 20] * (radiusMax - radiusMin);
      return {
        x: 100 + Math.cos(angle) * radius,
        y: 104 + Math.sin(angle) * radius,
        angle: (angle * 180) / Math.PI + 70,
      };
    };

    if (donut.topping === 'sprinkles' || donut.topping === 'zest') {
      const count = donut.topping === 'sprinkles' ? 17 : 12;
      for (let i = 0; i < count; i += 1) {
        const p = point(i, 43, 70);
        const color = colors[i % colors.length];
        const width = donut.topping === 'sprinkles' ? 9.5 : 7.5;
        const height = donut.topping === 'sprinkles' ? 3.7 : 2.8;
        output +=
          '<rect x="' +
          (p.x - width / 2).toFixed(1) +
          '" y="' +
          (p.y - height / 2).toFixed(1) +
          '" width="' +
          width +
          '" height="' +
          height +
          '" rx="' +
          height / 2 +
          '" fill="' +
          color +
          '" transform="rotate(' +
          p.angle.toFixed(1) +
          ' ' +
          p.x.toFixed(1) +
          ' ' +
          p.y.toFixed(1) +
          ')"/>';
      }
    }

    if (donut.topping === 'berries') {
      for (let i = 0; i < 7; i += 1) {
        const p = point(i + 3, 47, 65);
        const radius = 5.2 + randoms[i + 10] * 2.8;
        output +=
          '<g><circle cx="' +
          p.x.toFixed(1) +
          '" cy="' +
          p.y.toFixed(1) +
          '" r="' +
          radius.toFixed(1) +
          '" fill="' +
          colors[i % 2] +
          '"/><circle cx="' +
          (p.x - radius * 0.33).toFixed(1) +
          '" cy="' +
          (p.y - radius * 0.33).toFixed(1) +
          '" r="' +
          (radius * 0.28).toFixed(1) +
          '" fill="#FFF4F7" opacity=".55"/></g>';
      }
    }

    if (donut.topping === 'crumbs') {
      for (let i = 0; i < 19; i += 1) {
        const p = point(i + 2, 44, 70);
        const radius = 1.7 + randoms[i + 12] * 2.5;
        output +=
          '<circle cx="' +
          p.x.toFixed(1) +
          '" cy="' +
          p.y.toFixed(1) +
          '" r="' +
          radius.toFixed(1) +
          '" fill="' +
          colors[i % colors.length] +
          '"/>';
      }
      output +=
        '<path d="M52 92 C69 76 88 69 111 75 C128 80 139 92 142 106" fill="none" stroke="#FFFDF7" stroke-width="4" stroke-linecap="round" opacity=".66"/>';
      output +=
        '<path d="M58 120 C72 132 92 136 112 132" fill="none" stroke="#FFFDF7" stroke-width="3.3" stroke-linecap="round" opacity=".55"/>';
    }

    if (donut.topping === 'curls') {
      for (let i = 0; i < 11; i += 1) {
        const p = point(i + 4, 45, 69);
        const width = 6.5 + randoms[i + 8] * 4;
        output +=
          '<ellipse cx="' +
          p.x.toFixed(1) +
          '" cy="' +
          p.y.toFixed(1) +
          '" rx="' +
          width.toFixed(1) +
          '" ry="2.4" fill="' +
          colors[i % colors.length] +
          '" transform="rotate(' +
          p.angle.toFixed(1) +
