}

.checkout-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.34fr) minmax(320px, 0.86fr);
  min-height: 0;
  overflow-y: auto;
}

.checkout-form {
  min-width: 0;
  padding: 24px 28px 30px;
}

.form-section + .form-section {
  margin-top: 23px;
  padding-top: 22px;
  border-top: 1px dashed var(--line);
}

.form-section-head {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 13px;
}

.form-step {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 25px;
  height: 25px;
  border-radius: 8px;
  background: var(--plum);
  color: var(--cream);
  font-family: var(--display);
  font-size: 11px;
  font-weight: 800;
}

.form-section-head h3 {
  font-size: 18px;
  letter-spacing: -0.01em;
}

.form-section-head p {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10.5px;
}

.field-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 8px;
  min-width: 0;
}

.field > span {
  color: var(--plum-soft);
  font-size: 10.5px;
  font-weight: 800;
}

.field .optional {
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 700;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid rgba(70, 32, 60, 0.16);
  border-radius: 10px;
  background: var(--white);
  color: var(--plum);
  font-size: 12px;
  line-height: 1.4;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.field textarea {
  min-height: 58px;
  resize: vertical;
}

.field input::placeholder,
.field textarea::placeholder {
  color: #b39ca9;
  opacity: 1;
}

.field input:hover,
.field select:hover,
.field textarea:hover {
  border-color: rgba(70, 32, 60, 0.3);
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--coral);
  outline: 0;
  box-shadow: 0 0 0 3px rgba(255, 111, 97, 0.13);
  background: #fffdfa;
}

.field.has-error input,
.field.has-error select,
.field.has-error textarea {
  border-color: #d34b55;
  background: #fff9f8;
}

.field-error {
  min-height: 12px;
  color: #ba3d49;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.3;
}

.pay-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.pay-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  background: var(--white);
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.pay-option:hover {
  border-color: rgba(70, 32, 60, 0.3);
}

.pay-option.is-selected {
  border-color: var(--coral);
  background: #fffbf6;
  box-shadow: 0 0 0 3px rgba(255, 111, 97, 0.1);
}

.pay-option input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.pay-radio {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  background: var(--white);
}

.pay-option.is-selected .pay-radio {
  border-color: var(--coral);
}

.pay-option.is-selected .pay-radio::after {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
}

.pay-option-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 29px;
  height: 29px;
  border-radius: 8px;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 800;
}

.pay-option-cod {
  background: var(--yellow-soft);
  color: var(--plum);
}

.pay-option-cod .icon {
  width: 15px;
  height: 15px;
}

.pay-option-gcash {
  background: #eaf3ff;
  color: #0a7cf2;
}

.pay-option-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.2;
}

.pay-option-copy strong {
  font-size: 10.5px;
  font-weight: 800;
}

.pay-option-copy small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 8px;
}

.pay-option-tag {
  display: none;
}

.pay-option:focus-within {
  outline: 2px solid rgba(70, 32, 60, 0.34);
  outline-offset: 2px;
}

.gcash-panel {
  margin-top: 10px;
  padding: 11px;
  border: 1px dashed rgba(70, 32, 60, 0.18);
  border-radius: 12px;
  background: var(--mint-soft);
  animation: fadeIn 0.3s ease both;
}

.gcash-card {
  padding: 11px 12px;
  border-radius: 10px;
  background: var(--plum);
  color: var(--cream);
}

.gcash-card-top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.gcash-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #eaf3ff;
  color: #0a7cf2;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 800;
}

.gcash-card-top div {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.gcash-card-top div span {
  color: rgba(255, 248, 238, 0.56);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.gcash-card-top strong {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
}

.gcash-account {
  margin-left: auto;
  color: rgba(255, 248, 238, 0.7);
  font-size: 8.5px;
  font-weight: 700;
}

.gcash-amount {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 248, 238, 0.13);
}

.gcash-amount span {
  color: rgba(255, 248, 238, 0.58);
  font-size: 8.5px;
  font-weight: 700;
}

.gcash-amount strong {
  color: var(--yellow);
  font-family: var(--display);
  font-size: 21px;
  line-height: 1;
}

.gcash-card p {
  margin-top: 8px;
  color: rgba(255, 248, 238, 0.56);
  font-size: 8.5px;
  line-height: 1.45;
}

.gcash-panel > .field {
  margin-top: 9px;
  margin-bottom: 6px;
}

.upload-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 92px;
  margin-top: 2px;
  padding: 11px;
  border: 1.5px dashed rgba(70, 32, 60, 0.22);
  border-radius: 11px;
  background: var(--white);
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.upload-zone:hover,
.upload-zone.is-dragging {
  border-color: var(--coral);
  background: #fffaf5;
}

.upload-zone.has-error {
  border-color: #d34b55;
}

.upload-empty {
  text-align: center;
}

.upload-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  margin: 0 auto 4px;
  border-radius: 50%;
  background: var(--coral-soft);
  color: var(--coral-deep);
}

.upload-icon .icon {
  width: 14px;
  height: 14px;
}

.upload-empty p {
  color: var(--plum-soft);
  font-size: 9px;
}

.upload-empty p strong {
  color: var(--plum);
}

.upload-empty small {
  color: var(--muted);
  font-size: 7.5px;
}

.upload-preview {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
}

.upload-preview img {
  width: 47px;
  height: 58px;
  border-radius: 6px;
  object-fit: cover;
  box-shadow: 0 2px 8px rgba(70, 32, 60, 0.15);
}

.upload-file-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  line-height: 1.3;
}

.upload-file-copy strong {
  overflow: hidden;
  font-size: 9.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-file-copy span {
  color: var(--muted);
  font-size: 8px;
}

.upload-remove {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 50%;
  background: var(--coral-soft);
  color: var(--coral-deep);
}

.upload-remove .icon {
  width: 11px;
  height: 11px;
}

.order-summary {
  display: flex;
  flex-direction: column;
  padding: 25px 26px 24px;
  border-left: 1px solid var(--line);
  background: #fbeeda;
}

.summary-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 12px;
  border-bottom: 1px dashed rgba(70, 32, 60, 0.17);
}

.summary-head h3 {
  font-size: 20px;
}

.summary-head span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.summary-items {
  display: flex;
  flex-direction: column;
  gap: 9px;
  max-height: 209px;
  margin: 13px 0;
  overflow-y: auto;
  padding-right: 2px;
}

.summary-item {
  display: flex;
  align-items: center;
  gap: 9px;
}

.summary-thumb {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 41px;
  height: 41px;
  overflow: hidden;
  border-radius: 9px;
  background: var(--tone, var(--pink-soft));
}

.summary-thumb .donut-svg {
  width: 38px;
  height: 38px;
}

.summary-item-copy {
  flex: 1;
  min-width: 0;
  line-height: 1.25;
}

.summary-item-copy strong {
  display: block;
  overflow: hidden;
  font-size: 10px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summary-item-copy span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 8px;
}

.summary-item-price {
  flex: 0 0 auto;
  font-size: 10px;
  font-weight: 800;
}

.summary-empty {
  padding: 20px 0;
  color: var(--muted);
  font-size: 10px;
  text-align: center;
}

.summary-totals {
  margin-top: auto;
  padding: 12px 0 14px;
  border-top: 1px dashed rgba(70, 32, 60, 0.17);
}

.summary-totals > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 2px 0;
  color: var(--plum-soft);
  font-size: 10.5px;
}

.summary-totals > div strong {
  color: var(--plum);
  font-weight: 800;
}

.delivery-hint {
  display: block;
  margin: 4px 0 7px;
  color: var(--mint-deep);
  font-size: 8.5px;
  font-weight: 700;
}

.summary-grand {
  margin-top: 7px;
  padding-top: 9px !important;
  border-top: 1px solid rgba(70, 32, 60, 0.13);
  color: var(--plum) !important;
  font-family: var(--display);
  font-size: 17px !important;
  font-weight: 700;
}

.summary-grand strong {
  font-size: 25px;
  letter-spacing: -0.02em;
}

.secure-note {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin-top: 8px;
  color: var(--muted);
  font-size: 7.5px;
  line-height: 1.4;
  text-align: center;
  justify-content: center;
}

.secure-note .icon {
  width: 11px;
  height: 11px;
  color: var(--mint-deep);
}

.summary-trust {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 10px;
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 700;
  text-align: center;
}

.mini-pay {
  padding: 3px 5px;
  border: 1px solid rgba(70, 32, 60, 0.16);
  border-radius: 4px;
  color: var(--plum-soft);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.confirm-card {
  width: min(570px, 100%);
  padding: 28px 34px 27px;
  overflow: visible;
  text-align: center;
}

.confirm-art {
  position: relative;
  display: grid;
  place-items: center;
  width: 102px;
  height: 102px;
  margin: 0 auto 5px;
}

.confirm-check {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 73px;
  height: 73px;
  border-radius: 50%;
  background: var(--mint);
  color: var(--plum);
  box-shadow: 0 12px 25px rgba(47, 157, 125, 0.22);
}

.confirm-check .icon {
  width: 31px;
  height: 31px;
}

.confirm-ring {
  position: absolute;
  inset: 1px;
  border: 1.5px dashed rgba(70, 32, 60, 0.25);
  border-radius: 50%;
  animation: slowSpin 25s linear infinite;
}

.confetti {
  position: absolute;
  z-index: 1;
  width: 12px;
  height: 4px;
  border-radius: 999px;
}

.confetti-a {
  top: 9px;
  left: 1px;
  background: var(--coral);
  transform: rotate(34deg);
}

.confetti-b {
  top: 22px;
  right: 0;
  background: var(--yellow);
  transform: rotate(-23deg);
}

.confetti-c {
  bottom: 14px;
  left: 4px;
  background: var(--pink-deep);
  transform: rotate(-41deg);
}

.confetti-d {
  right: 6px;
  bottom: 20px;
  background: var(--mint-deep);
  transform: rotate(55deg);
}

.confirm-card .eyebrow {
  margin-top: 5px;
}

.confirm-card h2 {
  margin-top: 7px;
  font-size: clamp(35px, 4.5vw, 43px);
}

.confirm-lede {
  max-width: 430px;
  margin: 9px auto 0;
  color: var(--plum-soft);
  font-size: 13px;
  line-height: 1.55;
}

.confirm-ticket {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  margin-top: 18px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--line);
}

.confirm-ticket > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 13px;
  background: var(--white);
  text-align: left;
}

.confirm-ticket span {
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.confirm-ticket strong {
  overflow: hidden;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.confirm-note {
  margin-top: 12px;
  padding: 9px 12px;
  border-radius: 9px;
  background: var(--yellow-soft);
  color: var(--plum-soft);
  font-size: 10px;
  line-height: 1.45;
}

.confirm-actions {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.confirm-actions .btn {
  min-height: 42px;
  padding: 10px 17px;
  font-size: 12px;
}

.confirm-foot {
  display: block;
  margin-top: 15px;
  color: var(--muted);
  font-size: 8px;
}

.toasts {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 400;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(360px, calc(100% - 44px));
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 13px;
  border: 1px solid rgba(255, 248, 238, 0.12);
  border-radius: 12px;
  background: var(--plum);
  color: var(--cream);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.4;
  box-shadow: 0 16px 36px rgba(35, 13, 29, 0.27);
  pointer-events: auto;
  animation: toastIn 0.35s var(--ease) both;
}

.toast.is-leaving {
  animation: toastOut 0.25s ease both;
}

.toast-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--mint);
  color: var(--plum);
}

.toast-icon .icon {
  width: 12px;
  height: 12px;
}

.toast.is-error .toast-icon {
  background: var(--coral);
}

.toast-message {
  flex: 1;
}

.toast-action {
  flex: 0 0 auto;
  padding: 3px 7px;
  border-radius: 5px;
  background: rgba(255, 248, 238, 0.13);
  color: var(--yellow);
  font-size: 9px;
  font-weight: 800;
}

.toast-close {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: transparent;
  color: rgba(255, 248, 238, 0.5);
}

.toast-close .icon {
  width: 10px;
  height: 10px;
}

@keyframes riseIn {
  from {
    opacity: 0;
    transform: translateY(22px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes cardIn {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes floatDonut {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -10px;
  }
}

@keyframes pulseDot {
  0%,
  100% {
    box-shadow: 0 0 0 4px rgba(255, 111, 97, 0.12);
  }
  50% {
    box-shadow: 0 0 0 7px rgba(255, 111, 97, 0.04);
  }
}

@keyframes slowSpin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
}

@media (max-width: 1120px) {
  .hero-inner {
    grid-template-columns: minmax(0, 1fr) minmax(0, 0.9fr);
  }

  .hero-donut-main {
    left: 54px;
    width: 335px;
  }

  .hero-donut-mid {
    width: 145px;
  }

  .hero-orbit {
    transform: scale(0.9);
  }

  .orbit-one {
    top: 84px;
    right: 6px;
  }

  .orbit-two {
    top: 135px;
    right: 56px;
  }

  .donut-grid {
    gap: 15px;
  }

  .donut-media {
    height: 190px;
  }

  .donut-media .donut-svg {
    width: 156px;
  }

  .donut-body {
    padding: 14px;
  }

  .donut-body h3 {
    font-size: 19px;
  }

  .builder {
    gap: 38px;
  }

  .builder-card {
    padding: 15px;
  }

  .flavor-pick-name {
    font-size: 7.5px;
  }
}

@media (max-width: 980px) {
  .site-nav,
  .header-order-btn {
    display: none;
  }

  .mobile-menu-btn {
    display: grid;
  }

  .hero {
    padding-top: 38px;
  }

  .hero-inner {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .hero-copy {
    max-width: 610px;
    padding-bottom: 0;
  }

  .hero-copy h1 {
    font-size: clamp(52px, 8.7vw, 74px);
  }

  .hero-art {
    min-height: 518px;
    width: min(540px, 100%);
    margin: 0 auto;
  }

  .hero-donut-main {
    top: 110px;
    left: 92px;
    width: 345px;
  }

  .hero-donut-mid {
    top: 27px;
    right: 2px;
  }

  .orbit-one {
    top: 55px;
    right: 20px;
  }

  .orbit-two {
    top: 105px;
    right: 68px;
  }

  .perks-card {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    margin-top: 4px;
  }

  .perk {
    padding: 10px 18px;
  }

  .perk:nth-child(2) {
    border-right: 0;
  }

  .perk:nth-child(-n + 2) {
    border-bottom: 1px solid var(--line);
  }

  .donut-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .builder {
    grid-template-columns: 1fr;
    gap: 30px;
    max-width: 660px;
  }

  .builder-copy {
    max-width: 560px;
