body.admin-mode {
  background: #f4efe9;
}

.admin-shell {
  display: grid;
  grid-template-columns: 258px minmax(0, 1fr);
  min-height: 100vh;
  background: #f4efe9;
}

.admin-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 19px;
  height: 100vh;
  overflow-y: auto;
  padding: 25px 18px 20px;
  background: linear-gradient(178deg, #3d1a33 0%, #2c1025 100%);
  color: var(--cream);
}

.brand-admin {
  padding: 0 7px;
}

.brand-admin .brand-name {
  color: var(--cream);
}

.brand-admin .brand-sub {
  color: rgba(255, 248, 238, 0.42);
}

.admin-console-pill {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 5px;
  margin: -3px 7px 1px;
  padding: 5px 9px;
  border: 1px solid rgba(255, 248, 238, 0.13);
  border-radius: 999px;
  background: rgba(255, 248, 238, 0.08);
  color: var(--yellow);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.admin-console-pill .icon {
  width: 10px;
  height: 10px;
}

.admin-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 11px;
  border: 1px solid transparent;
  border-radius: 11px;
  background: transparent;
  color: rgba(255, 248, 238, 0.62);
  font-size: 11.5px;
  font-weight: 800;
  text-align: left;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.admin-nav-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 29px;
  height: 29px;
  border-radius: 8px;
  background: rgba(255, 248, 238, 0.08);
  color: rgba(255, 248, 238, 0.64);
}

.admin-nav-icon .icon {
  width: 15px;
  height: 15px;
}

.admin-nav-btn:hover {
  background: rgba(255, 248, 238, 0.07);
  color: var(--cream);
}

.admin-nav-btn.is-active {
  border-color: rgba(255, 248, 238, 0.12);
  background: var(--cream);
  color: var(--plum);
  box-shadow: 0 9px 22px rgba(17, 5, 13, 0.19);
}

.admin-nav-btn.is-active .admin-nav-icon {
  background: var(--pink-soft);
  color: var(--coral-deep);
}

.admin-nav-count,
.admin-nav-alert {
  display: grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  margin-left: auto;
  padding: 0 5px;
  border-radius: 999px;
  background: rgba(255, 248, 238, 0.11);
  color: rgba(255, 248, 238, 0.76);
  font-size: 8.5px;
  font-weight: 800;
}

.admin-nav-btn.is-active .admin-nav-count {
  background: var(--pink-soft);
  color: var(--plum);
}

.admin-nav-alert {
  background: var(--coral);
  color: var(--plum-dark);
}

.admin-nav-btn.is-active .admin-nav-alert {
  background: var(--coral);
  color: var(--plum-dark);
}

