  position: relative;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--white);
  color: var(--plum-soft);
}

.admin-bell .icon {
  width: 14px;
  height: 14px;
}

.bell-dot {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 6px;
  height: 6px;
  border: 1.5px solid var(--white);
  border-radius: 50%;
  background: var(--coral);
}

.admin-profile {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.admin-avatar {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border-radius: 50%;
  background: var(--pink);
  color: var(--plum);
  font-size: 9.5px;
  font-weight: 800;
}

.admin-profile-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.admin-profile-copy strong {
  font-size: 10px;
  font-weight: 800;
}

.admin-profile-copy small {
  color: var(--muted);
  font-size: 8px;
}

.admin-content {
  width: min(1460px, 100%);
  margin: 0 auto;
  padding: 27px 32px 50px;
  outline: 0;
}

.admin-greeting {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 22px;
}

.admin-eyebrow {
  color: var(--coral-deep);
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.admin-greeting h1 {
  margin-top: 5px;
  font-size: clamp(31px, 3.2vw, 42px);
  letter-spacing: -0.035em;
}

.admin-greeting p {
  max-width: 530px;
  margin-top: 5px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.admin-head-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
}

.admin-head-actions .btn {
  min-height: 39px;
  padding: 9px 14px;
  font-size: 10.5px;
}

.admin-head-actions .btn .icon {
  width: 14px;
  height: 14px;
}

.admin-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-stat {
  position: relative;
  min-width: 0;
  overflow: hidden;
  padding: 15px 16px 13px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: var(--white);
  box-shadow: 0 5px 13px rgba(70, 32, 60, 0.035);
}

.admin-stat::after {
  content: "";
  position: absolute;
  right: -26px;
  bottom: -35px;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: var(--stat-soft, var(--pink-soft));
  opacity: 0.68;
}

.admin-stat-top {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.admin-stat-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: var(--stat-soft, var(--pink-soft));
  color: var(--stat-ink, var(--coral-deep));
}

.admin-stat-icon .icon {
  width: 15px;
  height: 15px;
}

.stat-trend {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px 5px;
  border-radius: 5px;
  background: var(--mint-soft);
  color: #1e7b5f;
  font-size: 7.5px;
  font-weight: 800;
  white-space: nowrap;
}

.stat-trend.is-flat {
  background: var(--cream-3);
  color: var(--muted);
}

.admin-stat-label {
  position: relative;
  z-index: 1;
  margin-top: 11px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.03em;
}

.admin-stat-value {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 2px;
  overflow: hidden;
  font-family: var(--display);
  font-size: clamp(25px, 2.6vw, 32px);
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-stat-foot {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 8px;
  line-height: 1.35;
}

.stat-pink {
  --stat-soft: var(--pink-soft);
  --stat-ink: #bd5068;
}

.stat-yellow {
  --stat-soft: var(--yellow-soft);
  --stat-ink: #9d7417;
}

.stat-mint {
  --stat-soft: var(--mint-soft);
  --stat-ink: #217c60;
}

.stat-coral {
  --stat-soft: var(--coral-soft);
  --stat-ink: #c14b3f;
}

.admin-columns {
  display: grid;
  grid-template-columns: minmax(0, 1.62fr) minmax(280px, 0.82fr);
  align-items: start;
  gap: 14px;
  margin-top: 14px;
}

.admin-columns-wide {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.admin-side-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.admin-card {
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--white);
  box-shadow: 0 5px 13px rgba(70, 32, 60, 0.03);
}

.admin-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 13px;
}

.admin-card-head h2 {
  margin-top: 2px;
  font-size: 20px;
  letter-spacing: -0.02em;
}

.admin-card-kicker {
  display: block;
  color: var(--muted);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.admin-card-head-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.count-bubble {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--coral);
  color: var(--plum-dark);
  font-size: 8.5px;
  font-weight: 800;
}

.admin-text-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px;
  border-radius: 4px;
  background: transparent;
  color: var(--coral-deep);
  font-size: 8.5px;
  font-weight: 800;
  white-space: nowrap;
}

.admin-text-btn .icon {
  width: 11px;
  height: 11px;
}

.admin-text-btn:hover {
  color: var(--plum);
}

.admin-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.admin-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 9.5px;
}

.admin-table th {
  padding: 0 8px 8px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.admin-table th:first-child {
  padding-left: 2px;
}

.admin-table td {
  padding: 9px 8px;
  border-bottom: 1px solid rgba(70, 32, 60, 0.065);
  vertical-align: middle;
}

.admin-table tr:last-child td {
  border-bottom: 0;
}

.admin-table td:first-child {
  padding-left: 2px;
}

.admin-table tr:hover td {
  background: rgba(255, 248, 238, 0.52);
}

.order-id-btn {
  display: block;
  padding: 0;
  background: transparent;
  color: var(--plum);
  font-family: var(--display);
  font-size: 11.5px;
  font-weight: 800;
  line-height: 1.15;
  text-align: left;
}

.order-id-btn:hover {
  color: var(--coral-deep);
}

.cell-sub {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
}

.cell-main {
  display: block;
  overflow: hidden;
  max-width: 155px;
  font-size: 9.5px;
  font-weight: 800;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell-money {
  font-family: var(--display);
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
}

.cell-items {
  white-space: nowrap;
  font-weight: 700;
}

.table-manage {
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--white);
  color: var(--plum-soft);
  font-size: 7.5px;
  font-weight: 800;
  white-space: nowrap;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.table-manage:hover {
  border-color: var(--plum);
  background: var(--plum);
  color: var(--cream);
}

.admin-table .status-chip,
.admin-table .payment-chip {
  padding: 3px 6px;
  font-size: 6.7px;
  letter-spacing: 0.03em;
}

.attention-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.attention-item {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid rgba(70, 32, 60, 0.085);
  border-radius: 10px;
  background: var(--cream);
  transition: border-color 0.2s ease;
}

.attention-item:hover {
  border-color: rgba(70, 32, 60, 0.2);
}

.attention-thumb {
  display: grid;
  place-items: center;
  width: 34px;
  height: 40px;
  overflow: hidden;
  border-radius: 5px;
  background: #eaf3ff;
}

.attention-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.attention-thumb .icon {
  width: 15px;
  height: 15px;
  color: #0a7cf2;
}

.attention-meta {
  min-width: 0;
  line-height: 1.25;
}

.attention-meta strong {
  display: block;
  overflow: hidden;
  font-size: 8.8px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attention-meta span {
  display: block;
  overflow: hidden;
  margin-top: 2px;
  color: var(--muted);
  font-size: 7.3px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attention-amount {
  font-family: var(--display);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.attention-review {
  padding: 4px 6px;
  border-radius: 4px;
  background: var(--coral);
  color: var(--plum-dark);
  font-size: 6.5px;
  font-weight: 800;
  white-space: nowrap;
}

.attention-review:hover {
  background: var(--yellow);
}

.attention-empty {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 15px 10px;
  border-radius: 9px;
  background: var(--mint-soft);
  color: #1e7259;
  font-size: 8.5px;
  font-weight: 700;
  line-height: 1.4;
}

.attention-empty .icon {
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
}

.admin-mini-bars {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.mini-bar-row {
  display: grid;
  grid-template-columns: 55px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  font-size: 8px;
  font-weight: 700;
}

.mini-bar-label {
  color: var(--plum-soft);
  font-size: 7.8px;
}

.mini-bar-track {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--cream-3);
}

.mini-bar-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--campus, var(--pink-deep));
  transition: width 0.6s var(--ease);
}

.mini-bar-value {
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 800;
}

.mini-chart-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 11px;
  padding-top: 9px;
  border-top: 1px dashed var(--line);
  color: var(--muted);
  font-size: 7.5px;
}

.mini-chart-foot strong {
  color: var(--plum);
  font-size: 8px;
}

.seller-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.seller-row {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
}

.seller-thumb {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--tone, var(--pink-soft));
}

.seller-thumb .donut-svg {
  width: 29px;
  height: 29px;
}

.seller-info {
  min-width: 0;
}

.seller-info-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 8.5px;
  font-weight: 800;
}

.seller-info-top span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seller-info-top strong {
  font-size: 8px;
  color: var(--muted);
  white-space: nowrap;
}

.seller-bar {
  height: 5px;
  overflow: hidden;
  margin-top: 4px;
  border-radius: 999px;
  background: var(--cream-3);
}

.seller-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--coral);
}

.delivery-run {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.delivery-run-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px;
  border-radius: 8px;
  background: var(--cream);
}

.delivery-run-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: var(--yellow-soft);
  color: var(--plum);
}

.delivery-run-icon .icon {
  width: 12px;
  height: 12px;
}

.delivery-run-copy {
  flex: 1;
  min-width: 0;
}

.delivery-run-copy strong {
  display: block;
  overflow: hidden;
  font-size: 8.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.delivery-run-copy span {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 7px;
}

.delivery-run-time {
  color: var(--coral-deep);
  font-size: 7.5px;
  font-weight: 800;
  white-space: nowrap;
}

.admin-page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.admin-page-head h1 {
  margin-top: 4px;
  font-size: clamp(30px, 3vw, 40px);
}

.admin-page-head p {
  max-width: 490px;
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.admin-filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--white);
}

.admin-search {
  position: relative;
  flex: 1 1 220px;
  min-width: 160px;
}

.admin-search .icon {
  position: absolute;
  top: 50%;
  left: 10px;
  width: 13px;
  height: 13px;
  color: var(--muted);
  transform: translateY(-50%);
}

.admin-search input {
  width: 100%;
  padding: 8px 10px 8px 29px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--cream-2);
  color: var(--plum);
  font-size: 9.5px;
}

.admin-search input::placeholder {
  color: #b39ca9;
}

.admin-search input:focus {
  border-color: var(--coral);
  outline: 0;
  box-shadow: 0 0 0 2px rgba(255, 111, 97, 0.13);
}

.admin-select {
  min-width: 100px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--cream-2);
  color: var(--plum-soft);
  font-size: 9px;
  font-weight: 700;
}

.admin-select:focus {
  border-color: var(--coral);
  outline: 0;
}

.admin-count-note {
  margin-left: auto;
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.admin-list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 1px 0 12px;
}

.admin-list-head h2 {
  font-size: 17px;
}

.admin-list-head span {
  color: var(--muted);
  font-size: 8px;
}

.admin-orders-card {
  padding: 15px 17px;
}

.admin-orders-card .admin-table {
  font-size: 10px;
}

.admin-orders-card .admin-table th {
  font-size: 7px;
}

.admin-orders-card .admin-table td {
  padding: 10px 8px;
}

.admin-table .row-time {
  color: var(--muted);
  font-size: 7.5px;
}

.admin-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 190px;
  padding: 25px;
  text-align: center;
}

.admin-empty-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  margin-bottom: 9px;
  border-radius: 50%;
  background: var(--pink-soft);
  color: var(--coral-deep);
}

.admin-empty-icon .icon {
  width: 21px;
  height: 21px;
}

.admin-empty h3 {
  font-size: 17px;
}

.admin-empty p {
  max-width: 250px;
  margin-top: 3px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
}

.payment-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.verify-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.verify-summary-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--white);
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 700;
}

.verify-summary-pill strong {
  color: var(--plum);
  font-size: 8.5px;
}

.verify-summary-pill .dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--yellow);
}

.verify-summary-pill .dot.verified {
  background: var(--mint-deep);
}

.verify-summary-pill .dot.rejected {
  background: var(--coral);
}

.payment-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.72fr);
  align-items: start;
  gap: 14px;
}

.payment-verify-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.verify-card {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr) auto;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--white);
  box-shadow: 0 4px 11px rgba(70, 32, 60, 0.03);
}

.verify-receipt {
  position: relative;
  width: 92px;
  height: 112px;
  overflow: hidden;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: #eaf3ff;
  box-shadow: 0 4px 11px rgba(25, 64, 112, 0.13);
}

.verify-receipt img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.verify-receipt::after {
  content: "View";
  position: absolute;
  right: 4px;
  bottom: 4px;
  padding: 2px 4px;
  border-radius: 3px;
  background: rgba(51, 21, 43, 0.72);
  color: var(--white);
  font-size: 5.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.verify-info {
  min-width: 0;
}

.verify-info h3 {
  margin-top: 3px;
  font-size: 14px;
}

.verify-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px 8px;
  margin-top: 2px;
  color: var(--muted);
  font-size: 7.5px;
}

.verify-ref {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
  padding: 3px 6px;
  border-radius: 4px;
  background: var(--cream);
  color: var(--plum-soft);
  font-family: monospace;
  font-size: 7.5px;
  font-weight: 700;
}

.verify-amount {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  padding-top: 2px;
  text-align: right;
}

.verify-amount span {
  color: var(--muted);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.verify-amount strong {
  font-family: var(--display);
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1;
}

.verify-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 9px;
}

.verify-actions .btn {
  min-height: 27px;
  padding: 5px 9px;
  border-radius: 6px;
  font-size: 7.5px;
}

.verify-actions .btn .icon {
  width: 11px;
  height: 11px;
}

.btn-approve {
  background: var(--mint-deep);
  border-color: var(--mint-deep);
  color: var(--white);
  box-shadow: none;
}

.btn-approve:hover {
  background: #258268;
  border-color: #258268;
}

.btn-reject {
  background: transparent;
  border-color: rgba(196, 66, 56, 0.24);
  color: #b34138;
  box-shadow: none;
}

.btn-reject:hover {
  background: var(--coral-soft);
}

.verify-side {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.verify-side .admin-card {
  padding: 16px;
}

.verify-side h2 {
  font-size: 17px;
}

.verify-checklist {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.verify-checklist li {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  color: var(--plum-soft);
  font-size: 8.5px;
  line-height: 1.45;
}

.verify-checklist .icon {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  margin-top: 1px;
  color: var(--mint-deep);
}

.verified-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 10px;
}

.verified-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 7px;
  border-radius: 7px;
  background: var(--cream);
}

.verified-row-icon {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--mint);
  color: var(--plum);
}

.verified-row-icon .icon {
  width: 10px;
  height: 10px;
}

.verified-row-copy {
  flex: 1;
  min-width: 0;
}

.verified-row-copy strong {
  display: block;
  font-size: 8px;
  line-height: 1.2;
}

.verified-row-copy span {
  color: var(--muted);
  font-size: 6.8px;
}

.verified-row-amount {
  font-family: var(--display);
  font-size: 9.5px;
  font-weight: 700;
}

.campus-range-tabs {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--cream);
}

.campus-range-tab {
  padding: 5px 9px;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 800;
}

.campus-range-tab.is-active {
  background: var(--plum);
  color: var(--cream);
  box-shadow: 0 3px 7px rgba(70, 32, 60, 0.16);
}

.campus-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.8fr);
  align-items: start;
  gap: 14px;
}

.campus-chart {
  display: flex;
  flex-direction: column;
  gap: 17px;
  margin-top: 19px;
}

.campus-chart-row {
  display: grid;
  grid-template-columns: 115px minmax(0, 1fr) 68px;
  align-items: center;
  gap: 10px;
}

.campus-chart-name {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 9px;
  font-weight: 800;
}

.campus-dot {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--campus);
}

.campus-chart-name span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campus-chart-track {
  position: relative;
  height: 24px;
  overflow: hidden;
  border-radius: 6px;
  background: var(--cream);
}

.campus-chart-fill {
  height: 100%;
  min-width: 3px;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--campus), var(--campus-light));
  transition: width 0.7s var(--ease);
}

.campus-chart-value {
  text-align: right;
  font-family: var(--display);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.campus-chart-value span {
  display: block;
  color: var(--muted);
  font-family: var(--body);
  font-size: 6.8px;
  font-weight: 700;
}

.campus-chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 15px;
  padding-top: 11px;
  border-top: 1px dashed var(--line);
  color: var(--muted);
  font-size: 7px;
}

.campus-chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.campus-chart-legend strong {
  color: var(--plum);
}

.campus-summary-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  margin-top: 13px;
}

.campus-summary-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--cream-2);
}

.campus-summary-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: var(--campus-soft, var(--pink-soft));
  color: var(--plum);
}

.campus-summary-icon .icon {
  width: 13px;
  height: 13px;
}

.campus-summary-copy {
  flex: 1;
  min-width: 0;
}

.campus-summary-copy strong {
  display: block;
  font-size: 8.5px;
}

.campus-summary-copy span {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 6.8px;
}

.campus-summary-copy span strong {
  display: inline;
  font-size: 6.8px;
  color: var(--plum-soft);
}

.campus-summary-revenue {
  font-family: var(--display);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.campus-table-card {
  margin-top: 14px;
}

.campus-insight {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 13px;
  padding: 10px 11px;
  border-radius: 9px;
  background: var(--yellow-soft);
  color: var(--plum-soft);
  font-size: 8px;
  line-height: 1.5;
}

.campus-insight .icon {
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
  margin-top: 1px;
  color: #9e741a;
}

.campus-insight strong {
  color: var(--plum);
}

.report-top-items {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 13px;
}

.report-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.report-item-thumb {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--tone, var(--pink-soft));
}

.report-item-thumb .donut-svg {
  width: 26px;
  height: 26px;
}

.report-item-copy {
  flex: 1;
  min-width: 0;
}

.report-item-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 8px;
  font-weight: 800;
}

.report-item-top span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-item-top strong {
  color: var(--muted);
  font-size: 7.5px;
}

.report-item-bar {
  height: 4px;
  margin-top: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--cream-3);
}

.report-item-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--coral);
}

.admin-order-card {
  width: min(970px, 100%);
  max-height: 92vh;
  overflow-y: auto;
  border-radius: 25px;
  background: var(--cream);
}

.admin-order-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 21px 24px 16px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 253, 249, 0.75);
}

.admin-order-head h2 {
  margin-top: 3px;
  font-size: 29px;
}

.admin-order-head p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 9px;
}

.admin-order-body {
  padding: 18px 24px 24px;
}

.admin-order-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.8fr);
  align-items: start;
  gap: 14px;
}

.admin-order-left,
.admin-order-right {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.admin-detail-section {
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--white);
}

.admin-detail-section h3 {
  font-size: 15px;
  letter-spacing: -0.01em;
}

.detail-kicker {
  display: block;
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.admin-item-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 9px;
}

.admin-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px;
  border-radius: 8px;
  background: var(--cream-2);
}

.admin-item-thumb {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 37px;
  height: 37px;
  overflow: hidden;
  border-radius: 7px;
  background: var(--tone, var(--pink-soft));
}

.admin-item-thumb .donut-svg {
  width: 34px;
  height: 34px;
}

.admin-item-copy {
  flex: 1;
  min-width: 0;
}

.admin-item-copy strong {
  display: block;
  overflow: hidden;
  font-size: 9px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-item-copy span {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 7px;
}

.admin-item-qty {
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 800;
}

.admin-item-price {
  font-family: var(--display);
  font-size: 10.5px;
  font-weight: 700;
  white-space: nowrap;
}

.order-totals {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 9px;
  padding-top: 9px;
  border-top: 1px dashed var(--line);
}

.order-totals div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--muted);
  font-size: 8px;
}

.order-totals div strong {
  color: var(--plum);
  font-weight: 800;
}

.order-totals .order-total-grand {
  margin-top: 2px;
  padding-top: 5px;
  border-top: 1px solid var(--line);
  color: var(--plum);
  font-family: var(--display);
  font-size: 12.5px;
  font-weight: 700;
}

.order-totals .order-total-grand strong {
  font-size: 17px;
}

.delivery-detail-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 9px;
}

.detail-row {
  display: grid;
  grid-template-columns: 75px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  font-size: 8.5px;
}

.detail-row dt {
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 700;
}

.detail-row dd {
  margin: 0;
  color: var(--plum);
  font-weight: 700;
  line-height: 1.4;
  word-break: break-word;
}

.detail-note {
  margin-top: 9px;
  padding: 7px 8px;
  border-radius: 7px;
  background: var(--yellow-soft);
  color: var(--plum-soft);
  font-size: 7.5px;
  line-height: 1.45;
}

.detail-note strong {
  color: var(--plum);
}

.payment-panel {
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--white);
}

.payment-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.payment-panel-head h3 {
  font-size: 15px;
}

.payment-method-row {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 9px;
}

.payment-method-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 7px;
  background: #eaf3ff;
  color: #0a7cf2;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 800;
}

.payment-method-icon.cod {
  background: var(--yellow-soft);
  color: var(--plum);
}

.payment-method-icon.cod .icon {
  width: 14px;
  height: 14px;
}

.payment-method-copy {
  flex: 1;
  line-height: 1.2;
}

.payment-method-copy strong {
  display: block;
  font-size: 9px;
}

.payment-method-copy span {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 7px;
}

.receipt-display {
  margin-top: 9px;
}

.receipt-thumb-wrap {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 7px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--cream-2);
}

.receipt-open {
  width: 74px;
  height: 91px;
  overflow: hidden;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: #eaf3ff;
  box-shadow: 0 3px 9px rgba(25, 64, 112, 0.15);
}

.receipt-open img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.receipt-thumb-copy strong {
  display: block;
  font-size: 8px;
}

.receipt-thumb-copy span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 7px;
  line-height: 1.4;
}

.receipt-thumb-copy .ref-number {
  color: var(--plum-soft);
  font-family: monospace;
  font-size: 7.5px;
  font-weight: 700;
}

.payment-verify-actions {
  display: flex;
  gap: 5px;
  margin-top: 8px;
}

.payment-verify-actions .btn {
  min-height: 27px;
  padding: 5px 8px;
  border-radius: 6px;
  font-size: 7px;
}

.payment-verify-actions .btn .icon {
  width: 10px;
  height: 10px;
}

.admin-payment-alert {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 8px;
  padding: 7px 8px;
  border-radius: 7px;
  background: var(--yellow-soft);
  color: #7e5b13;
  font-size: 7px;
  line-height: 1.4;
}

.admin-payment-alert .icon {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  margin-top: 1px;
}

.status-panel {
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--white);
}

.status-panel h3 {
  font-size: 15px;
}

.admin-stepper {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 12px 0;
  padding: 0;
  list-style: none;
}

.astep {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding-bottom: 14px;
  color: var(--muted);
  font-size: 8px;
  line-height: 1.3;
}

.astep:last-child {
  padding-bottom: 0;
}

.astep::before {
  content: "";
  position: absolute;
  top: 13px;
  bottom: 0;
  left: 5px;
  width: 1px;
  background: var(--line);
}

.astep:last-child::before {
  display: none;
}

.adot {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  width: 11px;
  height: 11px;
  margin-top: 1px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  background: var(--white);
}

.astep.is-done {
  color: var(--plum-soft);
}

.astep.is-done .adot {
  border-color: var(--mint-deep);
  background: var(--mint);
}

.astep.is-current {
  color: var(--plum);
  font-weight: 800;
}

.astep.is-current .adot {
  border-color: var(--coral);
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 111, 97, 0.14);
}

.astep-copy {
  min-width: 0;
}

.astep-copy strong {
  display: block;
  font-size: 8.5px;
}

.astep-copy span {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 6.8px;
  font-weight: 600;
}

.admin-advance {
  width: 100%;
  min-height: 36px;
  font-size: 9.5px;
}

.status-note {
  margin-top: 7px;
  color: var(--muted);
  font-size: 7px;
  line-height: 1.4;
  text-align: center;
}

.admin-cancel-order {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
  padding: 6px;
  border-radius: 5px;
  background: transparent;
  color: #ad4c43;
  font-size: 7.5px;
  font-weight: 800;
}

.admin-cancel-order:hover {
  background: var(--coral-soft);
}

.admin-cancel-order .icon {
  width: 11px;
  height: 11px;
}

.receipt-lightbox {
  position: relative;
  width: min(380px, 100%);
  max-height: 91vh;
  padding: 11px;
  border-radius: 20px;
  background: var(--cream);
  box-shadow: var(--shadow-lg);
}

.receipt-lightbox img {
  width: 100%;
  max-height: calc(91vh - 76px);
  border-radius: 12px;
  object-fit: contain;
  background: #eaf3ff;
}

.receipt-lightbox p {
  padding: 7px 4px 2px;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 700;
  text-align: center;
}

.receipt-close {
  position: absolute;
  top: 17px;
  right: 17px;
  z-index: 2;
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(51, 21, 43, 0.72);
  color: var(--cream);
  box-shadow: 0 3px 9px rgba(0, 0, 0, 0.18);
}

.receipt-close:hover {
  background: var(--plum);
  color: var(--cream);
}

@media (max-width: 1220px) {
  .admin-shell {
    grid-template-columns: 230px minmax(0, 1fr);
  }

  .admin-content {
    padding-right: 24px;
    padding-left: 24px;
  }

  .admin-topbar {
    padding: 0 24px;
  }

  .admin-columns {
    grid-template-columns: minmax(0, 1.45fr) minmax(255px, 0.8fr);
  }

  .cell-main {
    max-width: 125px;
  }
}

@media (max-width: 1020px) {
  .admin-shell {
    display: block;
  }

  .admin-sidebar {
    position: relative;
    top: auto;
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px 16px;
    width: 100%;
    height: auto;
    overflow: visible;
    padding: 15px 22px;
  }

  .brand-admin {
    padding: 0;
  }

  .brand-admin .brand-mark {
    width: 36px;
    height: 36px;
  }

  .brand-admin .brand-name {
    font-size: 21px;
  }

  .admin-console-pill {
    margin: 0;
    font-size: 7px;
  }

  .admin-nav {
    order: 3;
    display: flex;
    flex-direction: row;
    width: 100%;
    overflow-x: auto;
    padding-bottom: 1px;
    scrollbar-width: none;
  }

  .admin-nav::-webkit-scrollbar {
    display: none;
  }

  .admin-nav-btn {
    width: auto;
    flex: 0 0 auto;
    padding: 7px 9px;
    font-size: 9px;
    border-radius: 8px;
  }

  .admin-nav-icon {
    width: 24px;
    height: 24px;
    border-radius: 6px;
  }

  .admin-nav-icon .icon {
    width: 13px;
    height: 13px;
  }

  .admin-side-card {
    display: none;
  }

  .admin-back {
    margin-left: auto;
    padding: 3px;
  }

  .admin-topbar {
    position: relative;
    min-height: 56px;
    padding: 0 22px;
  }

  .admin-content {
    padding: 22px 22px 45px;
  }

  .admin-stat-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .admin-columns {
    grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.8fr);
  }

