(function () {
  const GLAZE = window.GLAZE;
  if (!GLAZE) return;

  const store = GLAZE.store;
  const $ = function (selector, root) {
    return (root || document).querySelector(selector);
  };
  const $$ = function (selector, root) {
    return Array.prototype.slice.call((root || document).querySelectorAll(selector));
  };

  let cart = store.getCart();
  let menuFilter = 'All';
  let submitting = false;
  let currentMode = 'shop';
  const layerStack = [];
  const boxState = { size: 6, slots: [] };
  const uploadState = { dataUrl: '', name: '', size: 0 };
  const baseTitle = 'Glaze & Co. | Campus Donuts';

  function init() {
    hydrateStaticMedia();
    renderFilterChips();
    renderMenu();
    initializeBox();
    updateCartUI();
    updateOrderNav();
    setDeliveryDefaults();
    bindEvents();
    route();
  }

  function hydrateStaticMedia() {
    $$('[data-icon]').forEach(function (node) {
      node.innerHTML = GLAZE.icon(node.getAttribute('data-icon'));
    });
    $$('[data-donut-art]').forEach(function (node) {
      node.innerHTML = GLAZE.donutSVG(node.getAttribute('data-donut-art'), { hidden: true });
    });
  }

  function setDeliveryDefaults() {
    const dateInput = $('#deliveryDate');
    const timeInput = $('#timeSlot');
    if (!dateInput) return;
    const today = GLAZE.todayInputValue();
    dateInput.min = today;
    if (!dateInput.value) dateInput.value = today;
    if (timeInput && !timeInput.value) timeInput.value = GLAZE.timeSlots[0];
  }

  function renderFilterChips() {
    const wrap = $('#menuFilters');
    wrap.innerHTML = GLAZE.categories
      .map(function (category) {
        return (
          '<button type="button" class="filter-chip' +
          (category === menuFilter ? ' is-active' : '') +
          '" data-menu-filter="' +
          category +
          '" aria-pressed="' +
          (category === menuFilter) +
          '">' +
          category +
          '</button>'
        );
      })
      .join('');
  }

  function renderMenu() {
    const grid = $('#menuGrid');
    const items =
      menuFilter === 'All'
        ? GLAZE.donuts
        : GLAZE.donuts.filter(function (donut) {
            return donut.category === menuFilter;
          });

    grid.innerHTML = items
      .map(function (donut, index) {
        const badge = donut.badge
          ? '<span class="badge badge-' +
            donut.badgeTone +
            '">' +
            GLAZE.escapeHTML(donut.badge) +
            '</span>'
          : '';
        const rating = (4.8 + (index % 3) * 0.1).toFixed(1);
        return (
          '<article class="donut-card" style="--tone:' +
          donut.tone +
          '; animation-delay:' +
          index * 35 +
          'ms">' +
          '<div class="donut-media">' +
          badge +
          GLAZE.donutSVG(donut, { hidden: true }) +
          '</div>' +
          '<div class="donut-body">' +
          '<div class="donut-meta"><span class="donut-category">' +
          donut.category +
          '</span><span class="donut-rating">' +
          GLAZE.icon('star') +
          rating +
          '</span></div>' +
          '<h3>' +
          GLAZE.escapeHTML(donut.name) +
          '</h3>' +
          '<p>' +
          GLAZE.escapeHTML(donut.desc) +
          '</p>' +
          '<div class="donut-foot">' +
          '<span class="donut-price">₱' +
          donut.price +
          ' <small>/ piece</small></span>' +
          '<button type="button" class="add-donut" data-add-donut="' +
          donut.id +
          '" aria-label="Add ' +
          GLAZE.escapeHTML(donut.name) +
          ' to cart">' +
          GLAZE.icon('plus') +
          '</button>' +
          '</div></div></article>'
        );
      })
      .join('');

    $('#menuCount').textContent =
      items.length + ' ' + GLAZE.plural(items.length, 'flavour');
  }

  function findCartItem(key) {
    return cart.find(function (item) {
      return item.key === key;
    });
  }

  function persistCart() {
    store.saveCart(cart);
    updateCartUI();
  }

  function updateCartUI() {
    const totals = store.cartTotals(cart);
    const badge = $('#cartBadge');
    badge.textContent = totals.itemCount;
    badge.classList.toggle('is-zero', totals.itemCount === 0);
    renderCart();
  }

  function summarizeFlavors(ids) {
    const counts = {};
    (ids || []).forEach(function (id) {
      counts[id] = (counts[id] || 0) + 1;
    });
    return Object.keys(counts)
      .map(function (id) {
        return (counts[id] > 1 ? counts[id] + ' ' : '') + GLAZE.getDonut(id).name;
      })
      .join(' · ');
  }

  function itemDonut(item) {
    if (item.kind === 'box') {
      return GLAZE.getDonut((item.donutIds && item.donutIds[0]) || 'og-glazed');
    }
    return GLAZE.getDonut(item.donutId);
  }

  function cartItemMarkup(item) {
    const donut = itemDonut(item);
    const badge = item.kind === 'box' ? '<span class="cart-thumb-badge">x' + item.boxSize + '</span>' : '';
    return (
      '<div class="cart-item">' +
      '<div class="cart-thumb" style="--tone:' +
      donut.tone +
      '">' +
      GLAZE.donutSVG(donut, { hidden: true }) +
      badge +
      '</div>' +
      '<div class="cart-info"><div class="cart-item-top"><div><div class="cart-name">' +
      GLAZE.escapeHTML(item.name) +
      '</div><div class="cart-detail">' +
      GLAZE.escapeHTML(item.detail || '') +
      '</div></div><button type="button" class="cart-remove" data-cart-remove="' +
      GLAZE.escapeHTML(item.key) +
      '" aria-label="Remove ' +
      GLAZE.escapeHTML(item.name) +
      '">' +
      GLAZE.icon('trash') +
      '</button></div>' +
      '<div class="cart-bottom"><div class="qty-control">' +
      '<button type="button" class="qty-btn" data-cart-delta="-1" data-cart-key="' +
      GLAZE.escapeHTML(item.key) +
      '" aria-label="Decrease quantity">' +
      GLAZE.icon('minus') +
      '</button>' +
      '<span class="qty-value">' +
      item.qty +
      '</span>' +
      '<button type="button" class="qty-btn" data-cart-delta="1" data-cart-key="' +
      GLAZE.escapeHTML(item.key) +
      '" aria-label="Increase quantity">' +
      GLAZE.icon('plus') +
      '</button></div>' +
      '<span class="cart-price">' +
      GLAZE.money(item.unitPrice * item.qty) +
      '</span></div></div></div>'
    );
  }

  function emptyCartMarkup() {
    return (
      '<div class="drawer-empty"><div class="empty-art">' +
      GLAZE.donutSVG('strawberry-sprinkle', { hidden: true }) +
      '</div><h3>Your box is empty</h3><p>Soft dough and cheerful glaze are only a few taps away.</p>' +
      '<a class="btn btn-primary" href="#menu" data-close>Browse the donuts' +
      GLAZE.icon('arrowRight') +
      '</a></div>'
    );
  }

  function renderCart() {
    const body = $('#cartBody');
    const foot = $('#cartFoot');
    if (!body || !foot) return;
    const totals = store.cartTotals(cart);

    if (!cart.length) {
      body.innerHTML = emptyCartMarkup();
      foot.innerHTML = '';
      return;
    }

    body.innerHTML =
      '<div class="cart-items">' + cart.map(cartItemMarkup).join('') + '</div>';
    const remaining = Math.max(0, 499 - totals.subtotal);
    foot.innerHTML =
      '<div class="cart-subtotal"><span>Subtotal</span><strong>' +
      GLAZE.money(totals.subtotal) +
      '</strong></div>' +
      '<p class="cart-delivery-note">' +
      (totals.deliveryFee === 0
        ? '<strong>Free campus delivery unlocked.</strong>'
        : 'Delivery from ₱29 · add ' +
          GLAZE.money(remaining) +
          ' more for free delivery') +
      '</p>' +
      '<div class="cart-foot-actions"><button type="button" class="btn btn-primary btn-block" data-checkout>Checkout' +
      GLAZE.icon('arrowRight') +
      '</button><button type="button" class="text-button" data-cart-clear>Clear cart</button></div>';
  }

  function addDonutToCart(id, button) {
    const donut = GLAZE.getDonut(id);
    if (!donut) return;
    const key = 'donut:' + donut.id;
    const existing = findCartItem(key);
    if (existing) {
      existing.qty += 1;
    } else {
      cart.push({
        key: key,
        kind: 'donut',
        donutId: donut.id,
        name: donut.name,
        detail: 'Hand-glazed · 1 piece',
        unitPrice: donut.price,
        qty: 1,
      });
    }
    persistCart();
    showToast(donut.name + ' added to your cart.', {
      actionLabel: 'View cart',
      onAction: openCart,
    });
    if (button) {
      button.classList.add('is-added');
      button.innerHTML = GLAZE.icon('check');
      window.setTimeout(function () {
        button.classList.remove('is-added');
        if (document.contains(button)) button.innerHTML = GLAZE.icon('plus');
      }, 900);
    }
  }

  function changeCartQuantity(key, delta) {
    const item = findCartItem(key);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) {
      cart = cart.filter(function (entry) {
        return entry.key !== key;
      });
    }
    persistCart();
  }

  function removeCartItem(key) {
    const item = findCartItem(key);
    cart = cart.filter(function (entry) {
      return entry.key !== key;
    });
    persistCart();
    if (item) showToast(item.name + ' removed from your cart.');
  }

  function clearCart() {
    if (!cart.length) return;
    cart = [];
    persistCart();
    showToast('Your cart is clear. Ready for a fresh start.');
  }

  function initializeBox() {
    boxState.size = 6;
    boxState.slots = curatedSlots(6);
    renderBox();
  }

  function curatedSlots(size) {
    return Array.from({ length: size }, function (_, index) {
      return GLAZE.curatedBox[index % GLAZE.curatedBox.length];
    });
  }

  function renderBox() {
    const sizeInfo = GLAZE.getBoxSize(boxState.size);
    const sizeWrap = $('#boxSizes');
    sizeWrap.innerHTML = GLAZE.boxSizes
      .map(function (box) {
        return (
          '<button type="button" class="size-option' +
          (box.size === boxState.size ? ' is-active' : '') +
          '" data-box-size="' +
          box.size +
          '" aria-pressed="' +
          (box.size === boxState.size) +
          '">' +
          (box.popular ? '<span class="size-popular">Most loved</span>' : '') +
          '<span class="size-count">' +
          box.size +
          ' <small>donuts</small></span>' +
          '<span class="size-label">' +
          box.label +
          '</span>' +
          '<span class="size-price">₱' +
          box.price +
          '</span></button>'
        );
      })
      .join('');

    const filled = boxState.slots.filter(Boolean);
    const grid = $('#boxGrid');
    grid.style.setProperty('--box-cols', boxState.size === 4 ? 2 : 3);
    grid.innerHTML = boxState.slots
      .map(function (donutId, index) {
        if (!donutId) {
          return (
            '<button type="button" class="box-slot" data-box-slot="' +
            index +
            '" aria-label="Empty box slot ' +
            (index + 1) +
            '">' +
            '<span class="slot-plus">' +
            GLAZE.icon('plus') +
            '</span><span class="slot-number">' +
            (index + 1) +
            '</span></button>'
          );
        }
        const donut = GLAZE.getDonut(donutId);
        return (
          '<button type="button" class="box-slot is-filled" data-box-slot="' +
          index +
          '" style="--tone:' +
          donut.tone +
          '" aria-label="Remove ' +
          GLAZE.escapeHTML(donut.name) +
          ' from slot ' +
          (index + 1) +
          '">' +
          GLAZE.donutSVG(donut, { hidden: true }) +
          '<span class="slot-remove">' +
          GLAZE.icon('close') +
          '</span><span class="slot-number">' +
          (index + 1) +
          '</span></button>'
        );
      })
      .join('');

    $('#boxProgress').textContent = filled.length + ' of ' + boxState.size + ' picked';
    $('#boxPriceInline').textContent = sizeInfo.price;
    $('#boxAddPrice').textContent = '₱' + sizeInfo.price;

    const counts = {};
    filled.forEach(function (id) {
      counts[id] = (counts[id] || 0) + 1;
    });
    const isFull = filled.length === boxState.size;
    $('#boxPicker').innerHTML = GLAZE.donuts
      .map(function (donut) {
        const count = counts[donut.id] || 0;
        return (
          '<button type="button" class="flavor-pick" data-box-flavor="' +
          donut.id +
          '"' +
          (isFull ? ' disabled' : '') +
          ' aria-label="Add ' +
          GLAZE.escapeHTML(donut.name) +
          ' to the box">' +
          GLAZE.donutSVG(donut, { hidden: true }) +
          '<span class="flavor-pick-name">' +
          GLAZE.escapeHTML(donut.name) +
          '</span>' +
          (count ? '<span class="flavor-pick-count">' + count + '</span>' : '') +
          '</button>'
        );
      })
      .join('');

    const addButton = $('#boxAdd');
    addButton.disabled = !isFull;
    addButton.title = isFull ? 'Add your custom box to the cart' : 'Fill every slot first';
  }

  function addBoxToCart() {
    const filled = boxState.slots.filter(Boolean);
    if (filled.length !== boxState.size) {
      showToast('Fill every slot before adding your box.', { variant: 'error' });
      return;
    }
    const sizeInfo = GLAZE.getBoxSize(boxState.size);
    const sorted = filled.slice().sort();
    const key = 'box:' + boxState.size + ':' + sorted.join(',');
    const existing = findCartItem(key);
    if (existing) {
      existing.qty += 1;
    } else {
      cart.push({
        key: key,
        kind: 'box',
        boxSize: boxState.size,
        donutIds: filled.slice(),
        name: 'Custom Box of ' + boxState.size,
        detail: summarizeFlavors(filled),
        unitPrice: sizeInfo.price,
        qty: 1,
      });
    }
    persistCart();
    showToast(sizeInfo.label + ' added to your cart.', {
      actionLabel: 'View cart',
      onAction: openCart,
    });
  }

  function updateOrderNav() {
    const count = store.getCustomerOrders().length;
    const badge = $('#navOrderCount');
    if (!badge) return;
    badge.hidden = count === 0;
    badge.textContent = count > 9 ? '9+' : String(count);
  }

  function prepareCheckout() {
    setDeliveryDefaults();
    clearAllErrors();
    renderCheckoutSummary();
    const selected = $('input[name="payment"]:checked');
    setPaymentPanel(selected ? selected.value : 'cod');
  }

  function renderCheckoutSummary() {
    const container = $('#checkoutItems');
    if (!container) return;
    const totals = store.cartTotals(cart);
    if (!cart.length) {
      container.innerHTML = '<p class="summary-empty">Your basket is empty.</p>';
    } else {
      container.innerHTML = cart
        .map(function (item) {
          const donut = itemDonut(item);
          return (
            '<div class="summary-item"><div class="summary-thumb" style="--tone:' +
            donut.tone +
            '">' +
            GLAZE.donutSVG(donut, { hidden: true }) +
            '</div><div class="summary-item-copy"><strong>' +
            GLAZE.escapeHTML(item.name) +
            '</strong><span>' +
            item.qty +
            ' × ' +
            GLAZE.money(item.unitPrice) +
            '</span></div><span class="summary-item-price">' +
            GLAZE.money(item.unitPrice * item.qty) +
            '</span></div>'
          );
        })
        .join('');
    }

    $('#summaryItemCount').textContent =
      totals.itemCount +
      ' ' +
      GLAZE.plural(totals.itemCount, 'item') +
      ' in your box';
    $('#summarySubtotal').textContent = GLAZE.money(totals.subtotal);
    $('#summaryDelivery').textContent =
      totals.deliveryFee === 0 ? 'Free' : GLAZE.money(totals.deliveryFee);
    $('#summaryTotal').textContent = GLAZE.money(totals.total);
    $('#gcashAmount').textContent = GLAZE.money(totals.total);
    $('#placeOrderBtn').disabled = cart.length === 0;

    const hint = $('#deliveryHint');
    if (!cart.length) {
      hint.textContent = 'Campus delivery is ₱29 below ₱499.';
    } else if (totals.deliveryFee === 0) {
      hint.textContent = 'Free campus delivery unlocked — nice one.';
    } else {
      hint.textContent =
        'Add ' + GLAZE.money(499 - totals.subtotal) + ' more for free campus delivery.';
    }
