  function validateCheckout() {
    clearAllErrors();
    const value = function (id) {
      const node = $('#' + id);
      return node ? node.value.trim() : '';
    };
    let firstInvalid = null;

    const fail = function (name, message, node) {
      setFieldError(name, message);
      if (!firstInvalid) firstInvalid = node || $('#' + name);
    };

    if (value('fullName').length < 2) {
      fail('fullName', 'Please tell us who the donuts are for.');
    }

    const phoneClean = value('phone').replace(/\D/g, '');
    if (!/^09\d{9}$/.test(phoneClean) && !/^639\d{9}$/.test(phoneClean)) {
      fail('phone', 'Enter a valid mobile number, like 0917 123 4567.');
    }

    const email = value('email');
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      fail('email', 'That email does not look quite right.');
    }

    if (!value('campus')) {
      fail('campus', 'Choose your campus.');
    }

    if (value('building').length < 3) {
      fail('building', 'Add a building, room, or meeting spot.');
    }

    const dateValue = value('deliveryDate');
    if (!dateValue) {
      fail('deliveryDate', 'Pick a delivery date.');
    } else if (dateValue < GLAZE.todayInputValue()) {
      fail('deliveryDate', 'Choose today or a future date.');
    }

    if (!value('timeSlot')) {
      fail('timeSlot', 'Pick a delivery window.');
    }

    const payment = document.querySelector('input[name="payment"]:checked');
    const method = payment ? payment.value : 'cod';

    if (method === 'gcash') {
      const refClean = value('gcashRef').replace(/[^a-zA-Z0-9]/g, '');
      if (refClean.length < 6) {
        fail('gcashRef', 'Enter the reference number from your GCash receipt.');
      }
      if (!uploadState.dataUrl) {
        fail(
          'receipt',
          'Upload a clear screenshot or photo of your GCash receipt.',
          $('#receiptDrop')
        );
      }
    }

    if (firstInvalid) {
      if (firstInvalid.focus) firstInvalid.focus({ preventScroll: true });
      if (firstInvalid.scrollIntoView) {
        firstInvalid.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      showToast('A few details still need your attention.', { variant: 'error' });
      return false;
    }
    return true;
  }

  function processReceiptFile(file) {
    if (!file) return;
    const typeOk = /^image\/(png|jpe?g|webp)$/i.test(file.type);
    if (!typeOk) {
      setFieldError('receipt', 'Please upload a PNG, JPG, or WEBP image.');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setFieldError('receipt', 'That file is over 5 MB. Please choose a smaller image.');
      return;
    }

    const finish = function (dataUrl) {
      uploadState.dataUrl = dataUrl;
      uploadState.name = file.name;
      uploadState.size = file.size;
      $('#receiptThumb').src = dataUrl;
      $('#receiptFileName').textContent = file.name;
      $('#receiptFileSize').textContent =
        Math.max(1, Math.round(file.size / 1024)) + ' KB · ready to verify';
      $('#receiptEmpty').hidden = true;
      $('#receiptPreview').hidden = false;
      setFieldError('receipt', '');
      const error = $('[data-error-for="receipt"]');
      if (error) error.textContent = '';
      const drop = $('#receiptDrop');
      if (drop) drop.classList.remove('has-error');
    };

    const reader = new FileReader();
    reader.onload = function () {
      const raw = String(reader.result);
      const image = new Image();
      image.onload = function () {
        try {
          const maxSide = 1000;
          const scale = Math.min(1, maxSide / Math.max(image.width, image.height));
          const canvas = document.createElement('canvas');
          canvas.width = Math.round(image.width * scale);
          canvas.height = Math.round(image.height * scale);
          const context = canvas.getContext('2d');
          context.fillStyle = '#ffffff';
          context.fillRect(0, 0, canvas.width, canvas.height);
          context.drawImage(image, 0, 0, canvas.width, canvas.height);
          finish(canvas.toDataURL('image/jpeg', 0.78));
        } catch (error) {
          finish(raw);
        }
      };
      image.onerror = function () {
        finish(raw);
      };
      image.src = raw;
    };
    reader.onerror = function () {
      setFieldError('receipt', 'We could not read that file. Please try another image.');
    };
    reader.readAsDataURL(file);
  }

  function clearReceipt() {
    uploadState.dataUrl = '';
    uploadState.name = '';
    uploadState.size = 0;
    $('#receiptInput').value = '';
    $('#receiptThumb').removeAttribute('src');
    $('#receiptFileName').textContent = '';
    $('#receiptFileSize').textContent = '';
    $('#receiptEmpty').hidden = false;
    $('#receiptPreview').hidden = true;
    const error = $('[data-error-for="receipt"]');
    if (error) error.textContent = '';
    const drop = $('#receiptDrop');
    if (drop) drop.classList.remove('has-error');
  }

  function placeOrder(event) {
    event.preventDefault();
    if (submitting) return;
    if (!cart.length) {
      showToast('Your cart is empty. Add a donut first.', { variant: 'error' });
      return;
    }
    if (!validateCheckout()) return;

    const paymentInput = document.querySelector('input[name="payment"]:checked');
    const method = paymentInput ? paymentInput.value : 'cod';
    const totals = store.cartTotals(cart);
    const value = function (id) {
      const node = $('#' + id);
      return node ? node.value.trim() : '';
    };

    const order = {
      id: store.nextOrderId(),
      createdAt: new Date().toISOString(),
      source: 'customer',
      customer: {
        name: value('fullName'),
        phone: value('phone'),
        email: value('email'),
        campus: value('campus'),
        building: value('building'),
        date: value('deliveryDate'),
        time: value('timeSlot'),
        notes: value('notes'),
      },
      items: cart.map(function (item) {
        return Object.assign({}, item);
      }),
      subtotal: totals.subtotal,
      deliveryFee: totals.deliveryFee,
      total: totals.total,
      payment: {
        method: method,
        status: method === 'gcash' ? 'pending' : 'cod',
        reference: method === 'gcash' ? value('gcashRef') : null,
        receipt: method === 'gcash' ? uploadState.dataUrl : null,
      },
      status: 'pending',
    };

    submitting = true;
    const button = $('#placeOrderBtn');
    const original = button.innerHTML;
    button.disabled = true;
    button.textContent = 'Sending to the bakery...';

    store.addOrder(order);
    cart = [];
    store.saveCart(cart);
    updateCartUI();
    updateOrderNav();

    window.setTimeout(function () {
      submitting = false;
      button.disabled = false;
      button.innerHTML = original;
      closeLayer($('#checkoutModal'), { skipFocus: true });
      resetCheckout();
      showConfirmation(order);
    }, 420);
  }

  function resetCheckout() {
    const form = $('#checkoutForm');
    form.reset();
    clearAllErrors();
    clearReceipt();
    const today = GLAZE.todayInputValue();
    $('#deliveryDate').min = today;
    $('#deliveryDate').value = today;
    $('#timeSlot').value = GLAZE.timeSlots[0];
    const cod = form.querySelector('input[name="payment"][value="cod"]');
    if (cod) cod.checked = true;
    setPaymentPanel('cod');
    renderCheckoutSummary();
