    const steps = GLAZE.statuses
      .map(function (step, index) {
        let classes = 'track-step';
        if (index < statusIndex || (order.status === 'delivered' && index <= statusIndex)) {
          classes += ' is-done';
        }
        if (index === statusIndex) classes += ' is-current';
        return (
          '<span class="' +
