(function () {
  const GLAZE = window.GLAZE;
  if (!GLAZE) return;

  const store = GLAZE.store;
  const $ = function (selector, root) {
    return (root || document).querySelector(selector);
  };
  const $$ = function (selector, root) {
    return Array.prototype.slice.call((root || document).querySelectorAll(selector));
  };

  const state = {
    initialized: false,
    view: 'overview',
    range: 'week',
    currentOrderId: null,
    filters: {
      search: '',
      status: 'all',
      payment: 'all',
      campus: 'all',
    },
  };

  const campusPalette = {
    'Main Campus': { base: '#ff8fa3', light: '#ffd3dc', soft: '#ffe4e9' },
    'North Campus': { base: '#7fcbb1', light: '#c9ebdd', soft: '#e4f7ef' },
    'Riverside Campus': { base: '#f0ba4d', light: '#fbe4a8', soft: '#fff2cc' },
  };

  function ensureInitialized() {
    if (state.initialized) return;
    state.initialized = true;
    bindEvents();
  }

  function show() {
    ensureInitialized();
    store.ensureDemoData();
    $('#adminToday').textContent = GLAZE.formatLongDate(new Date());
    renderAdmin();
  }

  function bindEvents() {
    document.addEventListener('click', function (event) {
      const target = event.target;

      const viewButton = target.closest('[data-admin-view]');
      if (viewButton) {
        event.preventDefault();
        switchView(viewButton.getAttribute('data-admin-view'));
        return;
      }

      const rangeButton = target.closest('[data-campus-range]');
      if (rangeButton) {
        state.range = rangeButton.getAttribute('data-campus-range');
        renderAdmin();
        return;
      }

      const manageButton = target.closest('[data-manage-order]');
      if (manageButton) {
        openOrderModal(manageButton.getAttribute('data-manage-order'));
        return;
      }

      const verifyButton = target.closest('[data-verify-order]');
      if (verifyButton) {
        verifyPayment(verifyButton.getAttribute('data-verify-order'));
        return;
      }

      const rejectButton = target.closest('[data-reject-order]');
      if (rejectButton) {
        rejectPayment(rejectButton.getAttribute('data-reject-order'));
        return;
      }

      const advanceButton = target.closest('[data-advance-order]');
      if (advanceButton) {
        advanceOrder(advanceButton.getAttribute('data-advance-order'));
        return;
      }

      const cancelButton = target.closest('[data-cancel-order]');
      if (cancelButton) {
        cancelOrder(cancelButton.getAttribute('data-cancel-order'));
        return;
      }

      const receiptButton = target.closest('[data-open-receipt]');
      if (receiptButton) {
        openReceipt(receiptButton.getAttribute('data-open-receipt'));
        return;
      }

      if (target.closest('[data-export-orders]')) {
        exportOrders();
      }
    });

    $('#adminContent').addEventListener('input', function (event) {
      if (!event.target.matches('[data-admin-search]')) return;
      state.filters.search = event.target.value;
      renderAdminOrdersList();
    });

    $('#adminContent').addEventListener('change', function (event) {
      if (event.target.matches('[data-admin-status]')) {
        state.filters.status = event.target.value;
        renderAdminOrdersList();
      } else if (event.target.matches('[data-admin-payment]')) {
        state.filters.payment = event.target.value;
        renderAdminOrdersList();
      } else if (event.target.matches('[data-admin-campus]')) {
        state.filters.campus = event.target.value;
        renderAdminOrdersList();
      }
    });
  }

  function switchView(view) {
    if (!view) return;
    state.view = view;
    if (view === 'orders') {
      state.filters = { search: '', status: 'all', payment: 'all', campus: 'all' };
    }
    renderAdmin();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function renderAdmin() {
    const orders = store.getOrders();
    const pendingCount = orders.filter(function (order) {
      return order.payment.method === 'gcash' && order.payment.status === 'pending';
    }).length;

    $$('.admin-nav-btn').forEach(function (button) {
      button.classList.toggle('is-active', button.getAttribute('data-admin-view') === state.view);
    });
    const orderBadge = $('#adminOrderCount');
    orderBadge.textContent = orders.length;
    orderBadge.hidden = orders.length === 0;
    const paymentBadge = $('#adminPaymentCount');
    paymentBadge.textContent = pendingCount;
    paymentBadge.hidden = pendingCount === 0;

    const content = $('#adminContent');
    if (state.view === 'orders') {
      content.innerHTML = renderOrdersView(orders);
      renderAdminOrdersList();
    } else if (state.view === 'payments') {
      content.innerHTML = renderPaymentsView(orders);
    } else if (state.view === 'campus') {
      content.innerHTML = renderCampusView(orders);
    } else {
      content.innerHTML = renderOverview(orders);
    }

    if (state.currentOrderId && $('#adminOrderModal').classList.contains('is-open')) {
      const current = store.getOrder(state.currentOrderId);
      if (current) renderOrderModal(current);
    }
  }

  function itemCount(order) {
    return order.items.reduce(function (sum, item) {
      return sum + Number(item.qty || 1);
    }, 0);
  }

  function paymentInfo(order) {
    return GLAZE.paymentStatuses[order.payment.status] || GLAZE.paymentStatuses.cod;
  }

  function statusChip(order) {
    const status = GLAZE.getStatus(order.status);
    return '<span class="status-chip status-' + status.tone + '">' + status.short + '</span>';
  }

  function paymentChip(order) {
    const payment = paymentInfo(order);
    return '<span class="payment-chip status-' + payment.tone + '">' + payment.short + '</span>';
  }

  function orderRow(order) {
    const status = GLAZE.getStatus(order.status);
    const payment = paymentInfo(order);
    return (
      '<tr>' +
      '<td><button type="button" class="order-id-btn" data-manage-order="' +
      order.id +
      '">' +
      order.id +
      '</button><span class="cell-sub">' +
      GLAZE.timeAgo(order.createdAt) +
      '</span></td>' +
      '<td><span class="cell-main">' +
      GLAZE.escapeHTML(order.customer.name) +
      '</span><span class="cell-sub">' +
      GLAZE.escapeHTML(order.customer.campus) +
      '</span></td>' +
      '<td class="cell-items">' +
      itemCount(order) +
      ' ' +
      GLAZE.plural(itemCount(order), 'item') +
      '</td>' +
      '<td><span class="cell-money">' +
      GLAZE.money(order.total) +
      '</span></td>' +
      '<td><span class="payment-chip status-' +
      payment.tone +
      '" title="' +
      GLAZE.escapeHTML(payment.label) +
      '">' +
      payment.short +
      '</span></td>' +
      '<td><span class="status-chip status-' +
      status.tone +
      '">' +
      status.short +
      '</span></td>' +
      '<td><button type="button" class="table-manage" data-manage-order="' +
      order.id +
      '">Manage</button></td>' +
      '</tr>'
    );
  }

  function greeting() {
    const hour = new Date().getHours();
    if (hour < 12) return 'Good morning';
    if (hour < 18) return 'Good afternoon';
    return 'Good evening';
  }

  function trendMarkup(current, previous) {
    if (!previous) {
      return (
        '<span class="stat-trend' +
        (current ? '' : ' is-flat') +
        '">' +
        (current ? 'Fresh' : 'Quiet') +
        '</span>'
      );
    }
    const percent = Math.round(((current - previous) / previous) * 100);
    return (
      '<span class="stat-trend' +
      (percent < 0 ? ' is-down' : '') +
      '">' +
      (percent >= 0 ? '+' : '') +
      percent +
      '%</span>'
    );
  }

  function campusRevenue(orders, campusName) {
    return orders.reduce(function (sum, order) {
      return order.customer.campus === campusName ? sum + Number(order.total) : sum;
    }, 0);
  }

  function renderOverview(orders) {
    const today = GLAZE.startOfToday();
    const yesterday = GLAZE.yesterdayStart();
    const notCancelled = orders.filter(function (order) {
      return order.status !== 'cancelled';
    });
    const todayOrders = notCancelled.filter(function (order) {
      return new Date(order.createdAt) >= today;
    });
    const yesterdayOrders = notCancelled.filter(function (order) {
      const date = new Date(order.createdAt);
      return date >= yesterday && date < today;
    });
    const pending = orders.filter(function (order) {
      return (
        order.payment.method === 'gcash' &&
        order.payment.status === 'pending' &&
        order.status !== 'cancelled'
      );
    });
    const outForDelivery = orders.filter(function (order) {
      return order.status === 'out-for-delivery';
    });
    const activeKitchen = orders.filter(function (order) {
      return order.status === 'confirmed' || order.status === 'baking';
    });
    const revenueToday = todayOrders.reduce(function (sum, order) {
      return sum + Number(order.total);
    }, 0);
    const revenueYesterday = yesterdayOrders.reduce(function (sum, order) {
      return sum + Number(order.total);
    }, 0);
    const latest = orders.slice(0, 6);
    const pendingTotal = pending.reduce(function (sum, order) {
      return sum + Number(order.total);
    }, 0);

    const attention =
      pending.length === 0
        ? '<div class="attention-empty">' +
          GLAZE.icon('check') +
          'All GCash receipts are reviewed. The bakery can breathe.</div>'
        : '<div class="attention-list">' +
          pending
            .slice(0, 4)
            .map(function (order) {
              return (
                '<div class="attention-item">' +
                '<button type="button" class="attention-thumb" data-open-receipt="' +
                order.id +
                '" aria-label="View receipt for ' +
                order.id +
                '">' +
                (order.payment.receipt
                  ? '<img src="' + order.payment.receipt + '" alt="">'
                  : GLAZE.icon('receipt')) +
                '</button>' +
                '<div class="attention-meta"><strong>' +
                order.id +
                ' · ' +
                GLAZE.escapeHTML(order.customer.name) +
                '</strong><span>' +
                GLAZE.money(order.total) +
                ' · ' +
                GLAZE.timeAgo(order.createdAt) +
                '</span></div>' +
                '<button type="button" class="attention-review" data-manage-order="' +
                order.id +
                '">Review</button></div>'
              );
            })
            .join('') +
          '</div>';

    const campusRows = GLAZE.campuses
      .map(function (campus) {
        const revenue = campusRevenue(todayOrders, campus.name);
        return { campus: campus, revenue: revenue };
      })
      .sort(function (a, b) {
        return b.revenue - a.revenue;
      });
    const maxCampusRevenue = Math.max.apply(
      Math,
      campusRows.map(function (row) {
        return row.revenue;
      }).concat([1])
    );
    const campusBars = campusRows
      .map(function (row) {
        const color = (campusPalette[row.campus.name] || campusPalette['Main Campus']).base;
        return (
          '<div class="mini-bar-row"><span class="mini-bar-label">' +
          row.campus.short +
          '</span><div class="mini-bar-track"><div class="mini-bar-fill" style="--campus:' +
          color +
          ';width:' +
          (row.revenue / maxCampusRevenue) * 100 +
          '%"></div></div><span class="mini-bar-value">' +
          GLAZE.moneyShort(row.revenue) +
          '</span></div>'
        );
      })
      .join('');

    const weekCutoff = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const weekOrders = notCancelled.filter(function (order) {
      return new Date(order.createdAt) >= weekCutoff;
    });
    const topDonuts = getTopDonuts(weekOrders, 4);
    const sellers =
      topDonuts.length === 0
        ? '<div class="attention-empty">' + GLAZE.icon('sparkles') + 'The first batch is still in the oven.</div>'
        : '<div class="seller-list">' +
          topDonuts
            .map(function (item, index) {
              return (
                '<div class="seller-row"><div class="seller-thumb" style="--tone:' +
                item.donut.tone +
                '">' +
                GLAZE.donutSVG(item.donut, { hidden: true }) +
                '</div><div class="seller-info"><div class="seller-info-top"><span>' +
                GLAZE.escapeHTML(item.donut.name) +
                '</span><strong>' +
                item.count +
                ' sold</strong></div><div class="seller-bar"><span style="width:' +
                (item.count / topDonuts[0].count) * 100 +
                '%;background:' +
                (index === 0 ? 'var(--coral)' : index === 1 ? 'var(--pink-deep)' : 'var(--mint-deep)') +
                '"></span></div></div></div>'
              );
            })
            .join('') +
          '</div>';

    const upcoming = orders
      .filter(function (order) {
        return ['confirmed', 'baking', 'out-for-delivery'].indexOf(order.status) >= 0;
      })
      .sort(function (a, b) {
        return new Date(a.createdAt) - new Date(b.createdAt);
      })
      .slice(0, 4);
    const deliveryRun =
      upcoming.length === 0
        ? '<div class="attention-empty">' + GLAZE.icon('bike') + 'No boxes in motion right now. A rare, peaceful moment.</div>'
        : '<div class="delivery-run">' +
          upcoming
            .map(function (order) {
              const status = GLAZE.getStatus(order.status);
              return (
                '<button type="button" class="delivery-run-row" data-manage-order="' +
                order.id +
                '" style="text-align:left">' +
                '<span class="delivery-run-icon">' +
                GLAZE.icon(status.id === 'out-for-delivery' ? 'bike' : status.id === 'baking' ? 'sparkles' : 'bag') +
                '</span><span class="delivery-run-copy"><strong>' +
                order.id +
                ' · ' +
                GLAZE.escapeHTML(order.customer.name) +
                '</strong><span>' +
                GLAZE.escapeHTML(order.customer.campus) +
                ' · ' +
                GLAZE.escapeHTML(order.customer.building) +
                '</span></span><span class="delivery-run-time">' +
                order.customer.time.split(' – ')[0] +
                '</span></button>'
              );
            })
            .join('') +
          '</div>';

    return (
      '<div class="admin-greeting"><div><span class="admin-eyebrow">' +
      GLAZE.formatLongDate(new Date()) +
      '</span><h1>' +
      greeting() +
      ', Maya.</h1><p>Here is the sweet pulse of Glaze &amp; Co. today — orders, receipts, and everything heading out the door.</p></div><div class="admin-head-actions"><button type="button" class="btn btn-primary btn-small" data-admin-view="orders">Open live orders' +
      GLAZE.icon('arrowRight') +
      '</button></div></div>' +
      '<div class="admin-stat-grid">' +
      '<article class="admin-stat stat-pink"><div class="admin-stat-top"><span class="admin-stat-icon">' +
      GLAZE.icon('bag') +
      '</span>' +
      trendMarkup(todayOrders.length, yesterdayOrders.length) +
      '</div><p class="admin-stat-label">Orders today</p><strong class="admin-stat-value">' +
      todayOrders.length +
      '</strong><span class="admin-stat-foot">' +
      yesterdayOrders.length +
      ' yesterday · ' +
      activeKitchen.length +
      ' in the kitchen</span></article>' +
      '<article class="admin-stat stat-yellow"><div class="admin-stat-top"><span class="admin-stat-icon">' +
      GLAZE.icon('trendUp') +
      '</span>' +
      trendMarkup(revenueToday, revenueYesterday) +
      '</div><p class="admin-stat-label">Sales today</p><strong class="admin-stat-value">' +
      GLAZE.money(revenueToday) +
      '</strong><span class="admin-stat-foot">Across ' +
      GLAZE.plural(todayOrders.length, 'campus order') +
      '</span></article>' +
      '<article class="admin-stat stat-mint"><div class="admin-stat-top"><span class="admin-stat-icon">' +
      GLAZE.icon('wallet') +
      '</span><span class="stat-trend' +
      (pending.length ? '' : ' is-flat') +
      '">' +
      (pending.length ? 'Action' : 'Clear') +
      '</span></div><p class="admin-stat-label">GCash to verify</p><strong class="admin-stat-value">' +
      pending.length +
      '</strong><span class="admin-stat-foot">' +
      GLAZE.money(pendingTotal) +
      ' waiting for a look</span></article>' +
      '<article class="admin-stat stat-coral"><div class="admin-stat-top"><span class="admin-stat-icon">' +
      GLAZE.icon('bike') +
      '</span><span class="stat-trend is-flat">Live</span></div><p class="admin-stat-label">Out for delivery</p><strong class="admin-stat-value">' +
      outForDelivery.length +
      '</strong><span class="admin-stat-foot">Boxes currently on the move</span></article>' +
      '</div>' +
      '<div class="admin-columns">' +
      '<section class="admin-card admin-live-card"><header class="admin-card-head"><div><span class="admin-card-kicker">Floor view</span><h2>Live orders</h2></div><button type="button" class="admin-text-btn" data-admin-view="orders">View all' +
      GLAZE.icon('arrowRight') +
      '</button></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>' +
      latest.map(orderRow).join('') +
      '</tbody></table></div></section>' +
      '<div class="admin-side-stack"><section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">Receipt check</span><h2>Needs your eyes</h2></div><div class="admin-card-head-meta"><span class="count-bubble">' +
      pending.length +
      '</span><button type="button" class="admin-text-btn" data-admin-view="payments">Open' +
      GLAZE.icon('arrowRight') +
      '</button></div></header>' +
      attention +
      '</section><section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">By campus</span><h2>Today\'s pulse</h2></div></header><div class="admin-mini-bars">' +
      campusBars +
      '</div><div class="mini-chart-foot"><span>' +
      GLAZE.plural(todayOrders.length, 'order') +
      ' today</span><strong>' +
      GLAZE.money(revenueToday) +
      '</strong></div></section></div>' +
      '</div>' +
      '<div class="admin-columns admin-columns-wide">' +
      '<section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">Last seven days</span><h2>Top sellers</h2></div><span class="admin-text-btn">By quantity</span></header>' +
      sellers +
      '</section>' +
      '<section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">On the road</span><h2>Delivery run</h2></div><button type="button" class="admin-text-btn" data-admin-view="orders">Manage' +
      GLAZE.icon('arrowRight') +
      '</button></header>' +
      deliveryRun +
      '</section></div>'
    );
  }

  function renderOrdersView(orders) {
    const statusOptions = ['all']
      .concat(
        GLAZE.statuses.map(function (status) {
          return status.id;
        })
      )
      .concat(['cancelled']);
    const statusLabels = { all: 'All statuses', cancelled: 'Cancelled' };

    const paymentOptions = [
      ['all', 'All payments'],
      ['gcash-pending', 'GCash pending'],
      ['gcash-verified', 'GCash verified'],
      ['gcash-rejected', 'GCash rejected'],
      ['cod', 'Cash on delivery'],
    ];

    return (
      '<div class="admin-page-head"><div><span class="admin-eyebrow">Order book</span><h1>All orders</h1><p>Every box, every campus, every little detail in one place. Open an order to verify payment or move it along.</p></div><button type="button" class="btn btn-ghost btn-small" data-export-orders>' +
      GLAZE.icon('download') +
      'Export CSV</button></div>' +
      '<div class="admin-filter-bar">' +
      '<label class="admin-search">' +
      GLAZE.icon('search') +
      '<input type="search" data-admin-search placeholder="Search order, name, building..." value="' +
      GLAZE.escapeHTML(state.filters.search) +
      '" aria-label="Search orders"></label>' +
      '<select class="admin-select" data-admin-status aria-label="Filter by status">' +
      statusOptions
        .map(function (value) {
          return (
            '<option value="' +
            value +
            '"' +
            (state.filters.status === value ? ' selected' : '') +
            '>' +
            (statusLabels[value] || GLAZE.getStatus(value).short) +
            '</option>'
          );
        })
        .join('') +
      '</select>' +
      '<select class="admin-select" data-admin-payment aria-label="Filter by payment">' +
      paymentOptions
        .map(function (entry) {
          return (
            '<option value="' +
            entry[0] +
            '"' +
            (state.filters.payment === entry[0] ? ' selected' : '') +
            '>' +
            entry[1] +
            '</option>'
          );
        })
        .join('') +
      '</select>' +
      '<select class="admin-select" data-admin-campus aria-label="Filter by campus"><option value="all">All campuses</option>' +
      GLAZE.campuses
        .map(function (campus) {
          return (
            '<option value="' +
            GLAZE.escapeHTML(campus.name) +
            '"' +
            (state.filters.campus === campus.name ? ' selected' : '') +
            '>' +
            GLAZE.escapeHTML(campus.name) +
            '</option>'
          );
        })
        .join('') +
      '</select>' +
      '</div>' +
      '<div id="adminOrdersList">' +
      renderOrdersListMarkup(getFilteredOrders(orders)) +
      '</div>'
    );
  }

  function getFilteredOrders(orders) {
    const search = state.filters.search.trim().toLowerCase();
    return orders.filter(function (order) {
      if (state.filters.status !== 'all' && order.status !== state.filters.status) return false;
      if (state.filters.campus !== 'all' && order.customer.campus !== state.filters.campus) {
        return false;
      }
      if (state.filters.payment !== 'all') {
        if (state.filters.payment === 'cod' && order.payment.method !== 'cod') return false;
        if (
          state.filters.payment === 'gcash-pending' &&
          !(order.payment.method === 'gcash' && order.payment.status === 'pending')
        ) {
          return false;
        }
        if (
          state.filters.payment === 'gcash-verified' &&
          !(order.payment.method === 'gcash' && order.payment.status === 'verified')
        ) {
          return false;
        }
        if (
          state.filters.payment === 'gcash-rejected' &&
          !(order.payment.method === 'gcash' && order.payment.status === 'rejected')
        ) {
          return false;
        }
      }
      if (!search) return true;
      const haystack = [
        order.id,
        order.customer.name,
        order.customer.phone,
        order.customer.campus,
        order.customer.building,
        order.customer.email,
      ]
        .join(' ')
        .toLowerCase();
      return haystack.indexOf(search) >= 0;
    });
  }

