  function renderAdminOrdersList() {
    const container = $('#adminOrdersList');
    if (!container) return;
    container.innerHTML = renderOrdersListMarkup(getFilteredOrders(store.getOrders()));
  }

  function renderPaymentsView(orders) {
    const pending = orders
      .filter(function (order) {
        return (
          order.payment.method === 'gcash' &&
          order.payment.status === 'pending' &&
          order.status !== 'cancelled'
        );
      })
      .sort(function (a, b) {
        return new Date(a.createdAt) - new Date(b.createdAt);
      });
    const verified = orders.filter(function (order) {
      return order.payment.method === 'gcash' && order.payment.status === 'verified';
    });
    const rejected = orders.filter(function (order) {
      return order.payment.method === 'gcash' && order.payment.status === 'rejected';
    });
    const reviewed = verified
      .concat(rejected)
      .filter(function (order) {
        return order.status !== 'cancelled' || order.payment.status === 'rejected';
      })
      .sort(function (a, b) {
        return (
          new Date(b.payment.verifiedAt || b.createdAt) -
          new Date(a.payment.verifiedAt || a.createdAt)
        );
      })
      .slice(0, 5);

    const pendingMarkup = pending.length
      ? pending.map(paymentVerifyCard).join('')
      : '<div class="admin-card"><div class="admin-empty"><span class="admin-empty-icon">' +
        GLAZE.icon('check') +
        '</span><h3>All caught up</h3><p>No GCash receipts are waiting for review. The queue is completely clear.</p></div></div>';

    const reviewedMarkup = reviewed.length
      ? reviewed
          .map(function (order) {
            const good = order.payment.status === 'verified';
            return (
              '<div class="verified-row"><span class="verified-row-icon" style="' +
              (good ? '' : 'background:var(--coral-soft);color:#b34138') +
              '">' +
              GLAZE.icon(good ? 'check' : 'alert') +
              '</span><div class="verified-row-copy"><strong>' +
              order.id +
              ' · ' +
              GLAZE.escapeHTML(order.customer.name) +
              '</strong><span>' +
              (good ? 'Verified' : 'Rejected') +
              ' · ' +
              GLAZE.timeAgo(order.payment.verifiedAt || order.createdAt) +
              '</span></div><span class="verified-row-amount">' +
              GLAZE.money(order.total) +
              '</span></div>'
            );
          })
          .join('')
      : '<p class="admin-empty" style="min-height:60px;padding:8px"><span style="font-size:8px;color:var(--muted)">Reviewed receipts will show up here.</span></p>';

    return (
      '<div class="admin-page-head"><div><span class="admin-eyebrow">Money corner</span><h1>GCash payments</h1><p>Check that every receipt reference and amount matches, then approve the order for dispatch.</p></div><div class="verify-summary"><span class="verify-summary-pill"><span class="dot"></span>Pending <strong>' +
      pending.length +
      '</strong></span><span class="verify-summary-pill"><span class="dot verified"></span>Verified <strong>' +
      verified.length +
      '</strong></span><span class="verify-summary-pill"><span class="dot rejected"></span>Rejected <strong>' +
      rejected.length +
      '</strong></span></div></div>' +
      '<div class="payment-layout"><div><div class="admin-list-head"><h2>Awaiting verification</h2><span>' +
      GLAZE.plural(pending.length, 'receipt') +
      ' to check</span></div><div class="payment-verify-list">' +
      pendingMarkup +
      '</div></div><aside class="verify-side"><section class="admin-card"><span class="admin-card-kicker">Three quick checks</span><h2>Before you approve</h2><ul class="verify-checklist"><li>' +
      GLAZE.icon('check') +
      '<span>The GCash reference on the receipt matches the order.</span></li><li>' +
      GLAZE.icon('check') +
      '<span>The amount sent matches the order total exactly.</span></li><li>' +
      GLAZE.icon('check') +
      '<span>The sender name is recognisable, or the reference checks out.</span></li></ul></section><section class="admin-card"><div class="admin-card-head"><div><span class="admin-card-kicker">Latest decisions</span><h2>Recently reviewed</h2></div></div><div class="verified-list">' +
      reviewedMarkup +
      '</div></section></aside></div>'
    );
  }

  function paymentVerifyCard(order) {
