  function getTopDonuts(orders, limit) {
    const counts = {};
    orders.forEach(function (order) {
      order.items.forEach(function (item) {
        if (item.kind === 'box') {
          (item.donutIds || []).forEach(function (id) {
            counts[id] = (counts[id] || 0) + Number(item.qty || 1);
          });
        } else {
          counts[item.donutId] = (counts[item.donutId] || 0) + Number(item.qty || 1);
        }
      });
    });
    return Object.keys(counts)
      .map(function (id) {
        return { donut: GLAZE.getDonut(id), count: counts[id] };
      })
      .sort(function (a, b) {
        return b.count - a.count;
      })
      .slice(0, limit || 5);
  }

  function rangeCutoff(range) {
    if (range === 'today') return GLAZE.startOfToday();
    if (range === 'week') {
      const cutoff = GLAZE.startOfToday();
      cutoff.setDate(cutoff.getDate() - 6);
      return cutoff;
    }
    return null;
  }

  function renderCampusView(orders) {
    const cutoff = rangeCutoff(state.range);
    const filtered = orders.filter(function (order) {
      if (order.status === 'cancelled') return false;
      return !cutoff || new Date(order.createdAt) >= cutoff;
    });
    const totalRevenue = filtered.reduce(function (sum, order) {
      return sum + Number(order.total);
    }, 0);
    const avgOrder = filtered.length ? totalRevenue / filtered.length : 0;

    const campusStats = GLAZE.campuses.map(function (campus) {
      const campusOrders = filtered.filter(function (order) {
        return order.customer.campus === campus.name;
      });
      const revenue = campusOrders.reduce(function (sum, order) {
        return sum + Number(order.total);
      }, 0);
      const spots = {};
      campusOrders.forEach(function (order) {
        const spot = order.customer.building;
        spots[spot] = (spots[spot] || 0) + 1;
      });
      const popularSpot =
        Object.keys(spots).sort(function (a, b) {
          return spots[b] - spots[a];
        })[0] || 'No drops yet';
      return {
        campus: campus,
        orders: campusOrders.length,
        revenue: revenue,
        avg: campusOrders.length ? revenue / campusOrders.length : 0,
        popularSpot: popularSpot,
      };
    });

    const maxRevenue = Math.max.apply(
      Math,
      campusStats.map(function (entry) {
        return entry.revenue;
      }).concat([1])
    );
    const sortedCampus = campusStats.slice().sort(function (a, b) {
      return b.revenue - a.revenue;
    });
    const topCampus = sortedCampus[0];
    const topDonuts = getTopDonuts(filtered, 5);
    const maxDonut = topDonuts.length ? topDonuts[0].count : 1;
    const rangeLabels = { today: 'Today', week: 'This week', all: 'All time' };

    const chartRows = campusStats
      .map(function (entry) {
        const palette = campusPalette[entry.campus.name] || campusPalette['Main Campus'];
        return (
          '<div class="campus-chart-row"><span class="campus-chart-name"><span class="campus-dot" style="--campus:' +
          palette.base +
          '"></span><span>' +
          GLAZE.escapeHTML(entry.campus.name) +
          '</span></span><div class="campus-chart-track"><div class="campus-chart-fill" style="--campus:' +
          palette.base +
          ';--campus-light:' +
          palette.light +
          ';width:' +
          (entry.revenue / maxRevenue) * 100 +
          '%"></div></div><span class="campus-chart-value">' +
          GLAZE.moneyShort(entry.revenue) +
          '<span>' +
          entry.orders +
          ' ' +
          GLAZE.plural(entry.orders, 'order') +
          '</span></span></div>'
        );
      })
      .join('');

    const summary = sortedCampus
      .map(function (entry) {
        const palette = campusPalette[entry.campus.name] || campusPalette['Main Campus'];
        return (
          '<div class="campus-summary-item"><span class="campus-summary-icon" style="--campus-soft:' +
          palette.soft +
          '">' +
          GLAZE.icon('mapPin') +
          '</span><div class="campus-summary-copy"><strong>' +
          GLAZE.escapeHTML(entry.campus.name) +
          '</strong><span>' +
          entry.orders +
          ' orders · avg ' +
          GLAZE.moneyShort(entry.avg) +
          '</span></div><span class="campus-summary-revenue">' +
          GLAZE.moneyShort(entry.revenue) +
          '</span></div>'
        );
      })
      .join('');

    const tableRows = sortedCampus
      .map(function (entry) {
        const share = totalRevenue ? Math.round((entry.revenue / totalRevenue) * 100) : 0;
        return (
          '<tr><td><span class="cell-main">' +
          GLAZE.escapeHTML(entry.campus.name) +
          '</span><span class="cell-sub">' +
          entry.orders +
          ' orders</span></td><td><span class="cell-money">' +
          GLAZE.money(entry.revenue) +
          '</span></td><td>' +
          GLAZE.money(entry.avg) +
          '</td><td>' +
          Math.round(share) +
          '%</td><td><span class="cell-main">' +
          GLAZE.escapeHTML(entry.popularSpot) +
          '</span></td></tr>'
        );
      })
      .join('');

    const topDonutMarkup = topDonuts.length
      ? topDonuts
          .map(function (entry) {
            return (
              '<div class="report-item"><span class="report-item-thumb" style="--tone:' +
              entry.donut.tone +
              '">' +
              GLAZE.donutSVG(entry.donut, { hidden: true }) +
              '</span><div class="report-item-copy"><div class="report-item-top"><span>' +
              GLAZE.escapeHTML(entry.donut.name) +
              '</span><strong>' +
              entry.count +
              ' sold</strong></div><div class="report-item-bar"><span style="width:' +
              (entry.count / maxDonut) * 100 +
              '%"></span></div></div></div>'
            );
          })
          .join('')
      : '<div class="attention-empty">' +
        GLAZE.icon('sparkles') +
        'No donut sales in this window yet.</div>';

    return (
      '<div class="admin-page-head"><div><span class="admin-eyebrow">Campus report</span><h1>Campus sales</h1><p>Where the boxes are going and which flavours the campus is falling for. Cancelled orders are left out of the totals.</p></div><div class="campus-range-tabs" role="group" aria-label="Report range">' +
      ['today', 'week', 'all']
        .map(function (range) {
          return (
            '<button type="button" class="campus-range-tab' +
            (state.range === range ? ' is-active' : '') +
            '" data-campus-range="' +
            range +
            '">' +
            rangeLabels[range] +
            '</button>'
          );
        })
        .join('') +
      '</div></div>' +
      '<div class="campus-layout"><section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">' +
      rangeLabels[state.range] +
      '</span><h2>Sales by campus</h2></div><span class="admin-text-btn">' +
      GLAZE.plural(filtered.length, 'order') +
      ' · ' +
      GLAZE.money(totalRevenue) +
      '</span></header><div class="campus-chart">' +
      chartRows +
      '</div><div class="campus-chart-legend"><span>Average order <strong>' +
      GLAZE.money(avgOrder) +
      '</strong></span><span>Total orders <strong>' +
      filtered.length +
      '</strong></span><span>Total sales <strong>' +
      GLAZE.money(totalRevenue) +
      '</strong></span></div></section><aside class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">At a glance</span><h2>Campus snapshot</h2></div></header><div class="campus-summary-grid">' +
      summary +
      '</div><div class="campus-insight">' +
      GLAZE.icon('trendUp') +
      '<span>' +
      (topCampus
        ? '<strong>' +
          GLAZE.escapeHTML(topCampus.campus.name) +
          '</strong> leads this view with ' +
          GLAZE.money(topCampus.revenue) +
          ' in sales. Keep an eye on ' +
          GLAZE.escapeHTML(topCampus.popularSpot) +
          ' as the busiest drop-off point.'
        : 'Once orders start rolling in, campus insights will appear here.') +
      '</span></div></aside></div>' +
      '<div class="admin-columns"><section class="admin-card campus-table-card"><header class="admin-card-head"><div><span class="admin-card-kicker">Breakdown</span><h2>Campus performance</h2></div></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Campus</th><th>Revenue</th><th>Avg. order</th><th>Share</th><th>Busiest drop-off</th></tr></thead><tbody>' +
      tableRows +
      '</tbody></table></div></section><section class="admin-card"><header class="admin-card-head"><div><span class="admin-card-kicker">Popular right now</span><h2>Campus favourites</h2></div></header><div class="report-top-items">' +
      topDonutMarkup +
      '</div></section></div>'
    );
  }

  function openOrderModal(orderId) {
    const order = store.getOrder(orderId);
    if (!order) return;
    state.currentOrderId = order.id;
    renderOrderModal(order);
    const modal = $('#adminOrderModal');
    if (!modal.classList.contains('is-open')) {
      GLAZE.ui.openLayer(modal);
    }
  }

  function renderOrderModal(order) {
    const status = GLAZE.getStatus(order.status);
    const payment = paymentInfo(order);
    const statusIndex = GLAZE.getStatusIndex(order.status);
    const nextStatus = GLAZE.getNextStatus(order.status);
    const isGcash = order.payment.method === 'gcash';
    const paymentVerified = order.payment.status === 'verified';
    const requiresVerification =
      isGcash && nextStatus && (nextStatus === 'out-for-delivery' || nextStatus === 'delivered');
    const blocked = requiresVerification && !paymentVerified;
    const cancelled = order.status === 'cancelled';

    $('#adminOrderTitle').textContent = order.id;
    $('#adminOrderMeta').textContent =
      'Placed ' +
      GLAZE.formatDateTime(order.createdAt) +
      ' · ' +
      GLAZE.escapeHTML(order.customer.campus);

    const itemsMarkup = order.items
      .map(function (item) {
        const donut =
          item.kind === 'box'
            ? GLAZE.getDonut((item.donutIds && item.donutIds[0]) || 'og-glazed')
            : GLAZE.getDonut(item.donutId);
        return (
          '<div class="admin-item"><span class="admin-item-thumb" style="--tone:' +
          donut.tone +
          '">' +
          GLAZE.donutSVG(donut, { hidden: true }) +
          '</span><div class="admin-item-copy"><strong>' +
          GLAZE.escapeHTML(item.name) +
          '</strong><span>' +
          (item.kind === 'box' && item.donutIds
            ? GLAZE.escapeHTML(summarizeIds(item.donutIds))
            : 'Hand-glazed donut') +
          '</span></div><span class="admin-item-qty">×' +
          item.qty +
          '</span><span class="admin-item-price">' +
          GLAZE.money(item.unitPrice * item.qty) +
          '</span></div>'
        );
      })
      .join('');

    const stepper = cancelled
      ? ''
      : GLAZE.statuses
          .map(function (step, index) {
            const done = index < statusIndex || (order.status === 'delivered' && index <= statusIndex);
            const current = index === statusIndex;
            return (
              '<li class="astep' +
              (done ? ' is-done' : '') +
              (current ? ' is-current' : '') +
              '"><span class="adot"></span><span class="astep-copy"><strong>' +
              step.label +
              '</strong><span>' +
              (done ? 'Completed' : current ? 'In progress' : 'Waiting') +
              '</span></span></li>'
            );
          })
          .join('');

    let paymentAlert = '';
    if (isGcash) {
      if (order.payment.status === 'pending') {
        paymentAlert =
          '<div class="admin-payment-alert">' +
          GLAZE.icon('alert') +
          '<span>Verify this receipt before the order leaves the bakery.</span></div>';
      } else if (order.payment.status === 'rejected') {
        paymentAlert =
          '<div class="admin-payment-alert is-danger">' +
          GLAZE.icon('alert') +
          '<span>Payment rejected. Ask for a new receipt or verify again before dispatch.</span></div>';
      } else {
        paymentAlert =
          '<div class="admin-payment-alert is-success">' +
          GLAZE.icon('check') +
          '<span>Payment verified. The receipt matches this order total.</span></div>';
      }
    }

    const receiptMarkup = isGcash
      ? '<div class="receipt-display">' +
        (order.payment.receipt
          ? '<div class="receipt-thumb-wrap"><button type="button" class="receipt-open" data-open-receipt="' +
            order.id +
            '" aria-label="View full receipt"><img src="' +
            order.payment.receipt +
            '" alt="GCash receipt"></button><div class="receipt-thumb-copy"><strong>GCash receipt</strong><span>Ref <span class="ref-number">' +
            GLAZE.escapeHTML(order.payment.reference || '—') +
            '</span></span><span>Tap the receipt to check the details.</span></div></div>'
          : '<div class="admin-payment-alert is-danger">' +
            GLAZE.icon('alert') +
            '<span>No receipt uploaded for this GCash payment.</span></div>') +
        '</div>'
      : '';

    const verifyActions = isGcash
      ? order.payment.status !== 'verified'
        ? '<div class="payment-verify-actions"><button type="button" class="btn btn-approve" data-verify-order="' +
          order.id +
          '">' +
          GLAZE.icon('check') +
          'Verify payment</button><button type="button" class="btn btn-reject" data-reject-order="' +
          order.id +
          '">Reject</button></div>'
        : '<div class="payment-verify-actions"><button type="button" class="btn btn-reject" data-reject-order="' +
          order.id +
          '">Revoke verification</button></div>'
      : '';

    const actionButton = nextStatus && !cancelled
      ? '<button type="button" class="btn btn-primary admin-advance" data-advance-order="' +
        order.id +
        '"' +
        (blocked ? ' disabled' : '') +
        '>' +
        GLAZE.icon('arrowRight') +
        status.action +
        '</button>' +
        (blocked
          ? '<p class="status-note">Verify the GCash payment before dispatch.</p>'
          : '<p class="status-note">Update as the box moves through the bakery.</p>')
      : cancelled
