  function summarizeIds(ids) {
    const counts = {};
    (ids || []).forEach(function (id) {
      counts[id] = (counts[id] || 0) + 1;
    });
    return Object.keys(counts)
      .map(function (id) {
        return (counts[id] > 1 ? counts[id] + ' ' : '') + GLAZE.getDonut(id).name;
      })
      .join(' · ');
  }

  function afterMutation(orderId, message) {
    renderAdmin();
    if (state.currentOrderId && $('#adminOrderModal').classList.contains('is-open')) {
      const order = store.getOrder(state.currentOrderId);
      if (order) renderOrderModal(order);
    }
    if (message) GLAZE.ui.toast(message);
    if (orderId) state.currentOrderId = orderId;
  }

  function verifyPayment(orderId) {
    if (!orderId) return;
    store.updateOrder(orderId, function (order) {
      order.payment.status = 'verified';
      order.payment.verifiedAt = new Date().toISOString();
      return order;
    });
    afterMutation(orderId, 'GCash payment for ' + orderId + ' verified.');
  }

  function rejectPayment(orderId) {
    const order = store.getOrder(orderId);
    if (!order) return;
    const okay = window.confirm(
      'Reject the GCash payment for ' +
        order.id +
        '? The bakery will need a new receipt before dispatch.'
    );
    if (!okay) return;
    store.updateOrder(orderId, function (current) {
      current.payment.status = 'rejected';
      current.payment.verifiedAt = null;
      return current;
    });
    afterMutation(orderId, 'Payment for ' + orderId + ' marked as rejected.');
  }

  function advanceOrder(orderId) {
    const order = store.getOrder(orderId);
    if (!order) return;
    const next = GLAZE.getNextStatus(order.status);
    if (!next) return;
    if (
      order.payment.method === 'gcash' &&
      order.payment.status !== 'verified' &&
      (next === 'out-for-delivery' || next === 'delivered')
    ) {
      GLAZE.ui.toast('Verify the GCash payment before dispatch.', { variant: 'error' });
      return;
    }
    store.updateOrder(orderId, { status: next });
    GLAZE.ui.toast(orderId + ' moved to ' + GLAZE.getStatus(next).label.toLowerCase() + '.');
    afterMutation(orderId);
  }

  function cancelOrder(orderId) {
    const order = store.getOrder(orderId);
    if (!order) return;
    const okay = window.confirm('Cancel ' + orderId + '? This cannot be undone.');
    if (!okay) return;
    store.updateOrder(orderId, { status: 'cancelled' });
    GLAZE.ui.toast(orderId + ' has been cancelled.');
    afterMutation(orderId);
  }

  function openReceipt(orderId) {
    const order = store.getOrder(orderId);
    if (!order || !order.payment.receipt) {
      GLAZE.ui.toast('No receipt is attached to that order.', { variant: 'error' });
      return;
    }
    $('#receiptImage').src = order.payment.receipt;
    $('#receiptCaption').textContent =
      'GCash receipt · ' + order.id + ' · ' + GLAZE.money(order.total);
    GLAZE.ui.openLayer($('#receiptModal'));
  }

  function exportOrders() {
    const orders = getFilteredOrders(store.getOrders());
    if (!orders.length) {
      GLAZE.ui.toast('There are no orders to export with these filters.', { variant: 'error' });
      return;
    }
    const rows = [
      [
        'Order',
        'Placed',
        'Customer',
        'Phone',
        'Email',
        'Campus',
        'Drop-off',
        'Delivery date',
        'Time slot',
        'Items',
        'Subtotal',
        'Delivery fee',
        'Total',
        'Payment method',
        'Payment status',
        'Fulfillment',
      ],
    ];
    orders.forEach(function (order) {
      rows.push([
        order.id,
        GLAZE.formatDateTime(order.createdAt),
        order.customer.name,
        order.customer.phone,
        order.customer.email || '',
        order.customer.campus,
        order.customer.building,
        order.customer.date,
        order.customer.time,
        order.items
          .map(function (item) {
            return item.qty + ' x ' + item.name;
          })
          .join(' | '),
        order.subtotal.toFixed(2),
        order.deliveryFee.toFixed(2),
        order.total.toFixed(2),
        order.payment.method === 'gcash' ? 'GCash' : 'Cash on delivery',
        paymentInfo(order).label,
        GLAZE.getStatus(order.status).label,
      ]);
    });
    const csv = rows
      .map(function (row) {
        return row
          .map(function (cell) {
            return '"' + String(cell == null ? '' : cell).replace(/"/g, '""') + '"';
          })
          .join(',');
      })
      .join('\r\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'glaze-orders-' + GLAZE.todayInputValue() + '.csv';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    GLAZE.ui.toast('CSV exported with ' + GLAZE.plural(orders.length, 'order') + '.');
  }

  GLAZE.admin = {
    show: show,
    hide: function () {
      state.currentOrderId = null;
    },
  };
})();

