  if (error) error.textContent = '';
  const drop = $('#receiptDrop');
  if (drop) drop.classList.remove('has-error');
}

function placeOrder(event) {
  event.preventDefault();
  if (submitting) return;
  if (!cart.length) {
    showToast('Your cart is empty. Add a donut first.', { variant: 'error' });
    return;
  }
  if (!validateCheckout()) return;

  const paymentInput = document.querySelector('input[name="payment"]:checked');
  const method = paymentInput ? paymentInput.value : 'cod';
  const totals = store.cartTotals(cart);
  const value = function (id) {
    const node = $('#' + id);
    return node ? node.value.trim() : '';
  };

  const order = {
    id: store.nextOrderId(),
    createdAt: new Date().toISOString(),
    source: 'customer',
    customer: {
      name: value('fullName'),
      phone: value('phone'),
      email: value('email'),
      campus: value('campus'),
      building: value('building'),
      date: value('deliveryDate'),
      time: value('timeSlot'),
      notes: value('notes'),
    },
    items: cart.map(function (item) {
      return Object.assign({}, item);
    }),
    subtotal: totals.subtotal,
    deliveryFee: totals.deliveryFee,
    total: totals.total,
    payment: {
      method: method,
      status: method === 'gcash' ? 'pending' : 'cod',
      reference: method === 'gcash' ? value('gcashRef') : null,
      receipt: method === 'gcash' ? uploadState.dataUrl : null,
    },
    status: 'pending',
  };

  submitting = true;
  const button = $('#placeOrderBtn');
  const original = button.innerHTML;
  button.disabled = true;
  button.textContent = 'Sending to the bakery...';

  store.addOrder(order);
  cart = [];
  store.saveCart(cart);
  updateCartUI();
  updateOrderNav();

  window.setTimeout(function () {
    submitting = false;
    button.disabled = false;
    button.innerHTML = original;
    closeLayer($('#checkoutModal'), { skipFocus: true });
    resetCheckout();
    showConfirmation(order);
  }, 420);
}

function resetCheckout() {
  const form = $('#checkoutForm');
