  function closeTopLayer() {
    if (!layerStack.length) return;
    closeLayer(layerStack[layerStack.length - 1].el);
  }

  function closeAllLayers(options) {
    const settings = options || {};
    layerStack
      .slice()
      .reverse()
      .forEach(function (entry) {
        closeLayer(entry.el, settings);
      });
    $('#overlay').classList.remove('is-visible');
    if (!settings.keepScrollLock) document.body.classList.remove('no-scroll');
  }

  function showToast(message, options) {
    const settings = options || {};
    const region = $('#toastRegion');
    while (region.children.length >= 3) {
      region.removeChild(region.firstElementChild);
    }
    const toast = document.createElement('div');
    toast.className = 'toast' + (settings.variant === 'error' ? ' is-error' : '');

    const icon = document.createElement('span');
    icon.className = 'toast-icon';
    icon.innerHTML = GLAZE.icon(settings.variant === 'error' ? 'alert' : 'check');

    const copy = document.createElement('span');
    copy.className = 'toast-message';
    copy.textContent = message;

    toast.appendChild(icon);
    toast.appendChild(copy);

    if (settings.actionLabel && typeof settings.onAction === 'function') {
      const action = document.createElement('button');
      action.type = 'button';
      action.className = 'toast-action';
      action.textContent = settings.actionLabel;
      action.addEventListener('click', function () {
        dismissToast(toast);
        settings.onAction();
      });
      toast.appendChild(action);
    }

    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'toast-close';
    close.setAttribute('aria-label', 'Dismiss notification');
    close.innerHTML = GLAZE.icon('close');
    close.addEventListener('click', function () {
      dismissToast(toast);
    });
    toast.appendChild(close);

    region.appendChild(toast);
    window.setTimeout(function () {
      dismissToast(toast);
    }, 4200);
  }

  function dismissToast(toast) {
    if (!toast || !toast.parentElement) return;
    toast.classList.add('is-leaving');
    window.setTimeout(function () {
      if (toast.parentElement) toast.parentElement.removeChild(toast);
    }, 260);
  }

  function closeMobileNav() {
    const nav = $('#mobileNav');
    const button = $('#mobileMenuBtn');
    if (!nav || nav.hidden) return;
    nav.hidden = true;
    button.setAttribute('aria-expanded', 'false');
    button.setAttribute('aria-label', 'Open menu');
  }

  function toggleMobileNav() {
    const nav = $('#mobileNav');
    const button = $('#mobileMenuBtn');
    const isOpen = !nav.hidden;
    nav.hidden = isOpen;
    button.setAttribute('aria-expanded', String(!isOpen));
    button.setAttribute('aria-label', isOpen ? 'Open menu' : 'Close menu');
  }

  function route() {
    const isAdmin = window.location.hash.toLowerCase().indexOf('#admin') === 0;
    const site = $('#site');
    const adminShell = $('#adminShell');

    if (isAdmin) {
      closeAllLayers({ skipFocus: true });
      closeMobileNav();
      site.hidden = true;
      adminShell.hidden = false;
      document.body.classList.add('admin-mode');
      document.title = 'Admin console · Glaze & Co.';
      currentMode = 'admin';
      if (GLAZE.admin && GLAZE.admin.show) GLAZE.admin.show();
      window.scrollTo(0, 0);
    } else {
      const comingBack = currentMode === 'admin';
      adminShell.hidden = true;
      site.hidden = false;
      document.body.classList.remove('admin-mode');
      document.title = baseTitle;
      currentMode = 'shop';
      if (comingBack) {
        updateCartUI();
        updateOrderNav();
      }
    }
  }

  function bindEvents() {
    document.addEventListener('click', function (event) {
      const target = event.target;
      const addButton = target.closest('[data-add-donut]');
      if (addButton) {
        addDonutToCart(addButton.getAttribute('data-add-donut'), addButton);
        return;
      }

      const cartDelta = target.closest('[data-cart-delta]');
      if (cartDelta) {
        changeCartQuantity(
          cartDelta.getAttribute('data-cart-key'),
          Number(cartDelta.getAttribute('data-cart-delta'))
        );
        return;
      }

      const removeButton = target.closest('[data-cart-remove]');
      if (removeButton) {
        removeCartItem(removeButton.getAttribute('data-cart-remove'));
        return;
      }

      if (target.closest('[data-cart-clear]')) {
        clearCart();
        return;
      }

      if (target.closest('[data-checkout]')) {
        openCheckout();
        return;
      }

      if (target.closest('[data-open-cart]')) {
        event.preventDefault();
        closeMobileNav();
        openCart();
        return;
      }

      if (target.closest('[data-open-orders]')) {
        event.preventDefault();
        closeMobileNav();
        openOrders();
        return;
      }

      const sizeButton = target.closest('[data-box-size]');
      if (sizeButton) {
        boxState.size = Number(sizeButton.getAttribute('data-box-size'));
        boxState.slots = curatedSlots(boxState.size);
        renderBox();
        return;
      }

      const flavorButton = target.closest('[data-box-flavor]');
      if (flavorButton) {
        const emptyIndex = boxState.slots.indexOf(null);
        if (emptyIndex >= 0) {
          boxState.slots[emptyIndex] = flavorButton.getAttribute('data-box-flavor');
          renderBox();
        } else {
          showToast('Box is full — remove a donut to swap it out.');
        }
        return;
      }

      const slotButton = target.closest('[data-box-slot]');
      if (slotButton) {
        const index = Number(slotButton.getAttribute('data-box-slot'));
        if (boxState.slots[index]) {
          boxState.slots[index] = null;
          renderBox();
        }
        return;
      }

      if (target.closest('#boxShuffle')) {
        boxState.slots = Array.from({ length: boxState.size }, function () {
          return GLAZE.donuts[Math.floor(Math.random() * GLAZE.donuts.length)].id;
        });
        renderBox();
        showToast('One surprise box, coming right up.');
        return;
      }

      if (target.closest('#boxClear')) {
        boxState.slots = Array.from({ length: boxState.size }, function () {
          return null;
        });
        renderBox();
        return;
      }

      if (target.closest('#boxAdd')) {
        addBoxToCart();
        return;
      }

      if (target.closest('#confirmTrack')) {
        closeAllLayers({ skipFocus: true });
        renderOrdersDrawer();
        openLayer($('#ordersDrawer'));
        return;
      }

      const closer = target.closest('[data-close]');
      if (closer) {
        const layer = closer.closest('.drawer, .modal');
        if (layer) {
          closeLayer(layer);
        } else {
          closeTopLayer();
        }
        return;
      }

      if (target.closest('#mobileMenuBtn')) {
        toggleMobileNav();
        return;
      }

      const mobileLink = target.closest('.mobile-nav a, .mobile-nav button');
      if (mobileLink) {
        closeMobileNav();
      }

      if (
        !target.closest('.site-header') &&
        $('#mobileNav') &&
        !$('#mobileNav').hidden
      ) {
        closeMobileNav();
      }
    });

    $('#menuFilters').addEventListener('click', function (event) {
      const chip = event.target.closest('[data-menu-filter]');
      if (!chip) return;
      menuFilter = chip.getAttribute('data-menu-filter');
      renderFilterChips();
      renderMenu();
    });

    $('#checkoutForm').addEventListener('change', function (event) {
      if (event.target.name === 'payment') {
        setPaymentPanel(event.target.value);
        clearAllErrors();
      }
    });

    $('#checkoutForm').addEventListener('submit', placeOrder);

    const input = $('#receiptInput');
    const drop = $('#receiptDrop');

    input.addEventListener('change', function () {
      if (input.files && input.files[0]) processReceiptFile(input.files[0]);
      input.value = '';
    });

    drop.addEventListener('click', function (event) {
      if (event.target.closest('#receiptRemove')) {
        clearReceipt();
        return;
      }
      input.click();
    });

    drop.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        input.click();
      }
    });

    ['dragenter', 'dragover'].forEach(function (name) {
      drop.addEventListener(name, function (event) {
        event.preventDefault();
        drop.classList.add('is-dragging');
      });
    });

    ['dragleave', 'drop'].forEach(function (name) {
      drop.addEventListener(name, function (event) {
        event.preventDefault();
        drop.classList.remove('is-dragging');
      });
    });

    drop.addEventListener('drop', function (event) {
      const file = event.dataTransfer && event.dataTransfer.files[0];
      if (file) processReceiptFile(file);
    });

    window.addEventListener('hashchange', route);

    window.addEventListener('resize', function () {
      if (window.innerWidth > 980) closeMobileNav();
    });

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && layerStack.length) {
        closeTopLayer();
        return;
      }
      if (event.key !== 'Tab' || !layerStack.length) return;
      const top = layerStack[layerStack.length - 1].el;
      const focusables = $$(
        'button:not([disabled]), [href], input:not([type="hidden"]):not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
        top
      ).filter(function (node) {
        return node.offsetParent !== null || node === document.activeElement;
      });
      if (!focusables.length) {
        event.preventDefault();
        return;
      }
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    });

    $('#overlay').addEventListener('click', closeTopLayer);
  }

  GLAZE.ui = {
    openLayer: openLayer,
    closeLayer: closeLayer,
    closeTopLayer: closeTopLayer,
    closeAllLayers: closeAllLayers,
    toast: showToast,
    refresh: function () {
