    },
    refreshCustomerUi: function () {
      cart = store.getCart();
      updateCartUI();
      updateOrderNav();
    },
    formatDeliveryDate: formatDeliveryDate,
  };

  document.addEventListener('DOMContentLoaded', init);
})();

