(function () {
  const GLAZE = (window.GLAZE = window.GLAZE || {});
  const ORDER_KEY = 'glazeCo.orders.v1';
  const CART_KEY = 'glazeCo.cart.v1';
  const DEMO_KEY = 'glazeCo.demoSeeded.v1';
  const memory = {};

  function readRaw(key) {
    try {
      const value = window.localStorage.getItem(key);
      if (value !== null) return value;
    } catch (error) {
      // Fall back to the in-memory copy below.
    }
    return Object.prototype.hasOwnProperty.call(memory, key) ? memory[key] : null;
  }

  function writeRaw(key, value) {
    memory[key] = value;
    try {
      window.localStorage.setItem(key, value);
    } catch (error) {
      // The UI can still work for this session when storage is unavailable.
    }
  }

  function readJSON(key, fallback) {
    const raw = readRaw(key);
    if (!raw) return fallback;
    try {
      const parsed = JSON.parse(raw);
      return parsed == null ? fallback : parsed;
    } catch (error) {
      return fallback;
    }
  }

  function readOrders() {
    const orders = readJSON(ORDER_KEY, []);
    return Array.isArray(orders) ? orders : [];
  }

  function writeOrders(orders) {
    writeRaw(ORDER_KEY, JSON.stringify(orders));
  }

  function sortOrders(orders) {
    return orders.slice().sort(function (a, b) {
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    });
  }

  function nextOrderId() {
    const orders = readOrders();
    const highest = orders.reduce(function (max, order) {
      const numeric = Number(String(order.id || '').replace(/\D/g, ''));
      return Number.isFinite(numeric) ? Math.max(max, numeric) : max;
    }, 2051);
    return 'GZ-' + (highest + 1);
  }

  function addOrder(order) {
    const orders = readOrders();
    orders.push(order);
    writeOrders(sortOrders(orders));
    return order;
  }

  function getOrder(id) {
    return readOrders().find(function (order) {
      return order.id === id;
    });
  }

  function updateOrder(id, updater) {
    const orders = readOrders();
    const index = orders.findIndex(function (order) {
      return order.id === id;
    });
    if (index < 0) return null;
    const current = orders[index];
    const next =
      typeof updater === 'function'
        ? updater(Object.assign({}, current, { payment: Object.assign({}, current.payment) }))
        : Object.assign({}, current, updater);
    orders[index] = next;
    writeOrders(sortOrders(orders));
    return next;
  }

  function getOrders() {
    return sortOrders(readOrders());
  }

  function getCustomerOrders() {
    return getOrders().filter(function (order) {
      return order.source !== 'demo';
    });
  }

  function getCart() {
    const cart = readJSON(CART_KEY, []);
    return Array.isArray(cart) ? cart : [];
  }

  function saveCart(cart) {
    writeRaw(CART_KEY, JSON.stringify(Array.isArray(cart) ? cart : []));
  }

  function cartTotals(items) {
    const list = Array.isArray(items) ? items : [];
    const subtotal = list.reduce(function (sum, item) {
      return sum + Number(item.unitPrice || 0) * Number(item.qty || 1);
    }, 0);
    const itemCount = list.reduce(function (sum, item) {
      return sum + Number(item.qty || 1);
    }, 0);
    const deliveryFee = subtotal > 0 && subtotal < 499 ? 29 : 0;
    return {
      subtotal: subtotal,
      deliveryFee: deliveryFee,
      total: subtotal + deliveryFee,
      itemCount: itemCount,
    };
  }

  function daysAgoIso(minutesAgo, daysAgo) {
    const date = new Date();
    date.setDate(date.getDate() - (daysAgo || 0));
    return new Date(date.getTime() - minutesAgo * 60000).toISOString();
  }

  function dateInputFromIso(iso) {
    const date = new Date(iso);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day;
  }

  function xmlEscape(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function makeDemoReceipt(name, amount, reference, dateLabel, status) {
    const amountText = GLAZE.money(amount).replace('₱', '\u20B1');
    const svg =
      '<svg xmlns="http://www.w3.org/2000/svg" width="360" height="560" viewBox="0 0 360 560">' +
      '<rect width="360" height="560" rx="28" fill="#F0F4FA"/>' +
      '<rect width="360" height="164" rx="28" fill="#0A7CF2"/>' +
      '<rect y="120" width="360" height="44" fill="#0A7CF2"/>' +
      '<circle cx="47" cy="48" r="20" fill="#FFFFFF"/>' +
      '<text x="47" y="57" text-anchor="middle" font-family="Arial, sans-serif" font-size="25" font-weight="800" fill="#0A7CF2">G</text>' +
      '<text x="78" y="58" font-family="Arial, sans-serif" font-size="28" font-weight="800" fill="#FFFFFF">GCash</text>' +
      '<text x="28" y="98" font-family="Arial, sans-serif" font-size="12" font-weight="700" letter-spacing="1.6" fill="#CBE6FF">PAYMENT RECEIPT</text>' +
      '<circle cx="316" cy="48" r="18" fill="#FFFFFF" fill-opacity=".16"/>' +
      '<path d="M309 48l5 5 10-11" fill="none" stroke="#FFFFFF" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<rect x="22" y="132" width="316" height="394" rx="20" fill="#FFFFFF"/>' +
      '<circle cx="180" cy="184" r="27" fill="#E4F7EE"/>' +
      '<path d="M168 184l8 8 17-18" fill="none" stroke="#0B9B62" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<text x="180" y="232" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#738196">Payment sent</text>' +
      '<text x="180" y="278" text-anchor="middle" font-family="Arial, sans-serif" font-size="35" font-weight="800" fill="#10233E">' +
      amountText +
      '</text>' +
      '<rect x="44" y="310" width="272" height="1" fill="#E6EBF2"/>' +
      '<text x="44" y="338" font-family="Arial, sans-serif" font-size="11" fill="#7D8A9C">Recipient</text>' +
      '<text x="44" y="358" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#24364D">Glaze &amp; Co.</text>' +
      '<text x="44" y="388" font-family="Arial, sans-serif" font-size="11" fill="#7D8A9C">GCash number</text>' +
      '<text x="44" y="408" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#24364D">0917 123 4567</text>' +
      '<text x="216" y="388" font-family="Arial, sans-serif" font-size="11" fill="#7D8A9C">Sent by</text>' +
      '<text x="216" y="408" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#24364D">' +
      xmlEscape(name) +
      '</text>' +
      '<text x="44" y="438" font-family="Arial, sans-serif" font-size="11" fill="#7D8A9C">Reference no.</text>' +
      '<text x="44" y="458" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#24364D">' +
      xmlEscape(reference) +
      '</text>' +
      '<text x="216" y="438" font-family="Arial, sans-serif" font-size="11" fill="#7D8A9C">Date</text>' +
      '<text x="216" y="458" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#24364D">' +
      xmlEscape(dateLabel) +
      '</text>' +
      '<rect x="44" y="478" width="92" height="26" rx="13" fill="#E7F8EF"/>' +
      '<text x="90" y="495" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#0B8A5A">' +
      xmlEscape(status || 'Completed') +
      '</text>' +
      '<text x="180" y="550" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" fill="#8391A4">Demo receipt · Glaze &amp; Co. campus bakery</text>' +
      '</svg>';
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }

  function donutLine(donutId, qty) {
    const donut = GLAZE.getDonut(donutId);
    return {
      kind: 'donut',
      donutId: donut.id,
      name: donut.name,
      unitPrice: donut.price,
      qty: qty,
      detail: 'Hand-glazed donut',
    };
  }

  function boxLine(size, donutIds, qty) {
    const box = GLAZE.getBoxSize(size);
    return {
      kind: 'box',
      boxSize: size,
      donutIds: donutIds.slice(),
      name: 'Custom Box of ' + size,
      unitPrice: box.price,
      qty: qty || 1,
      detail: box.label,
    };
  }

  function makeDemoOrder(config) {
    const createdAt = daysAgoIso(config.minutesAgo || 0, config.daysAgo || 0);
    const subtotal = config.items.reduce(function (sum, item) {
      return sum + item.unitPrice * item.qty;
    }, 0);
    const deliveryFee = subtotal >= 499 ? 0 : 29;
    const total = subtotal + deliveryFee;
    const payment =
      config.method === 'cod'
        ? { method: 'cod', status: 'cod', reference: null, receipt: null }
        : {
            method: 'gcash',
            status: config.paymentStatus || 'pending',
            reference: config.reference,
            receipt: makeDemoReceipt(
              config.name,
              total,
              config.reference,
              GLAZE.formatShortDate(createdAt) + ', ' + GLAZE.formatTime(createdAt),
              config.paymentStatus === 'rejected' ? 'Refunded' : 'Completed'
            ),
            verifiedAt: config.paymentStatus === 'verified' ? createdAt : null,
          };
    return {
      id: config.id,
      createdAt: createdAt,
      source: 'demo',
      customer: {
        name: config.name,
        phone: config.phone,
        email: config.email || '',
        campus: config.campus,
        building: config.building,
        date: config.deliveryDate || dateInputFromIso(createdAt),
        time: config.time || GLAZE.timeSlots[1],
        notes: config.notes || '',
      },
      items: config.items,
      subtotal: subtotal,
      deliveryFee: deliveryFee,
      total: total,
      payment: payment,
      status: config.status,
    };
  }

