      }),
    ];
  }

  function ensureDemoData() {
    if (readRaw(DEMO_KEY) === '1') return;
    const current = readOrders();
    const existingIds = new Set(
      current.map(function (order) {
        return order.id;
      })
    );
    const demos = buildDemoOrders().filter(function (order) {
      return !existingIds.has(order.id);
    });
    writeOrders(sortOrders(current.concat(demos)));
    writeRaw(DEMO_KEY, '1');
  }

  GLAZE.store = {
    getOrders: getOrders,
    getCustomerOrders: getCustomerOrders,
    getOrder: getOrder,
    addOrder: addOrder,
    updateOrder: updateOrder,
    nextOrderId: nextOrderId,
    getCart: getCart,
    saveCart: saveCart,
    cartTotals: cartTotals,
    ensureDemoData: ensureDemoData,
    makeDemoReceipt: makeDemoReceipt,
  };

  GLAZE.computeCartTotals = cartTotals;
})();

  }

  .admin-page-head .btn {
    margin-top: 11px;
  }

  .admin-filter-bar {
    padding: 8px;
  }

  .admin-search {
    flex-basis: 100%;
  }

  .admin-select {
    flex: 1;
    min-width: 86px;
  }

  .admin-count-note {
    flex-basis: 100%;
    margin-left: 0;
  }

  .verify-card {
    grid-template-columns: 74px minmax(0, 1fr);
    gap: 9px;
    padding: 9px;
  }

  .verify-receipt {
    width: 74px;
    height: 101px;
  }

  .verify-amount {
    grid-column: 2;
    align-items: flex-start;
    padding-top: 0;
    text-align: left;
  }

  .verify-amount strong {
    font-size: 17px;
  }

  .verify-actions {
    grid-column: 1 / -1;
    margin-top: 2px;
  }

  .verify-actions .btn {
    flex: 1;
    min-height: 30px;
  }

  .verify-card {
    grid-template-areas:
      "receipt info"
      "receipt amount"
      "actions actions";
  }

  .verify-receipt {
    grid-area: receipt;
  }

  .verify-info {
    grid-area: info;
  }

  .verify-amount {
    grid-area: amount;
  }

  .verify-actions {
    grid-area: actions;
  }

  .campus-chart-row {
    grid-template-columns: 86px minmax(0, 1fr) 54px;
    gap: 7px;
  }

  .campus-chart-name {
    font-size: 8px;
  }

  .campus-chart-value {
    font-size: 9.5px;
  }

  .admin-order-card {
    max-height: 100vh;
    border-radius: 0;
  }

  .admin-order-modal {
    padding: 0;
  }

  .admin-order-head {
    padding: 16px 16px 13px;
  }

  .admin-order-head h2 {
    font-size: 25px;
  }

  .admin-order-body {
    padding: 13px 14px 20px;
  }

  .admin-order-grid {
    grid-template-columns: 1fr;
  }

  .admin-order-right {
    order: -1;
  }

  .admin-order-left {
    order: 0;
  }

  .payment-panel,
  .status-panel {
    padding: 12px;
  }

  .admin-detail-section {
    padding: 12px;
  }

  .receipt-thumb-wrap {
    grid-template-columns: 66px minmax(0, 1fr);
  }

  .receipt-open {
    width: 66px;
    height: 82px;
  }

  .payment-verify-actions .btn {
    flex: 1;
    min-height: 30px;
  }

  .admin-advance {
    min-height: 38px;
    font-size: 10px;
  }

  .detail-row {
    grid-template-columns: 68px minmax(0, 1fr);
  }
}

@media (max-width: 460px) {
  .admin-stat-grid {
    gap: 8px;
  }

  .admin-stat-icon {
    width: 27px;
    height: 27px;
  }

  .admin-stat-icon .icon {
    width: 13px;
    height: 13px;
  }

  .stat-trend {
    font-size: 6.5px;
    padding: 2px 4px;
  }

  .admin-card-head h2 {
    font-size: 18px;
  }

  .admin-nav-btn > span:nth-child(2) {
    font-size: 8px;
  }

  .admin-nav-icon {
    display: none;
  }

  .admin-live-card .admin-table th:nth-child(4),
  .admin-live-card .admin-table td:nth-child(4) {
    display: none;
  }

  .admin-live-card .admin-table th:nth-child(2),
  .admin-live-card .admin-table td:nth-child(2) {
    max-width: 90px;
  }

  .campus-chart-row {
    grid-template-columns: 75px minmax(0, 1fr) 45px;
  }

  .campus-chart-value span {
    display: none;
  }

  .brand-admin .brand-sub {
    display: none;
  }

