const fs = require('fs');
const path = require('path');

const BASE = 'http://127.0.0.1:8000/index.html';
const CDP_BASE = 'http://127.0.0.1:9222';
const OUT = path.join(process.env.TEMP, 'glaze-qa');
fs.mkdirSync(OUT, { recursive: true });

const consoleMessages = [];
const exceptions = [];
const logEntries = [];
const checks = [];
const failures = [];

function check(name, condition, detail) {
  const pass = Boolean(condition);
  checks.push({ name, pass, detail: detail === undefined ? '' : detail });
  console.log((pass ? 'PASS ' : 'FAIL ') + name + (detail === undefined ? '' : ' :: ' + detail));
  if (!pass) failures.push(name + (detail === undefined ? '' : ' :: ' + detail));
  return pass;
}

function sleep(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

async function openTarget() {
  const response = await fetch(CDP_BASE + '/json/new?about:blank', { method: 'PUT' });
  if (!response.ok) throw new Error('Unable to create CDP target: ' + response.status);
  return response.json();
}

class CDP {
  constructor(webSocketDebuggerUrl) {
    this.ws = new WebSocket(webSocketDebuggerUrl);
    this.nextId = 1;
    this.pending = new Map();
  }

  open() {
    const self = this;
    return new Promise(function (resolve, reject) {
      self.ws.addEventListener('open', function () {
        self.ws.addEventListener('message', function (event) {
          self.handleMessage(JSON.parse(event.data));
        });
        resolve();
      });
      self.ws.addEventListener('error', function (event) {
        reject(new Error('CDP websocket error: ' + (event.message || 'unknown')));
      });
    });
  }

  handleMessage(message) {
    if (message.id && this.pending.has(message.id)) {
      const pending = this.pending.get(message.id);
      this.pending.delete(message.id);
      if (message.error) {
        pending.reject(new Error(pending.method + ': ' + message.error.message));
      } else {
        pending.resolve(message.result);
      }
      return;
    }
    if (message.method === 'Runtime.consoleAPICalled') {
      consoleMessages.push({
        type: message.params.type,
        args: message.params.args.map(function (arg) {
          return arg.value !== undefined ? arg.value : arg.description;
        }),
      });
    } else if (message.method === 'Runtime.exceptionThrown') {
      const details = message.params.exceptionDetails;
      exceptions.push({
        text: details.text,
        description: details.exception && details.exception.description,
        url: details.url,
        line: details.lineNumber,
        column: details.columnNumber,
      });
    } else if (message.method === 'Log.entryAdded') {
      logEntries.push({
        level: message.params.entry.level,
        text: message.params.entry.text,
        url: message.params.entry.url,
      });
    }
  }

  send(method, params) {
    const self = this;
    return new Promise(function (resolve, reject) {
      const id = self.nextId++;
      self.pending.set(id, { resolve, reject, method });
      self.ws.send(JSON.stringify({ id, method, params: params || {} }));
    });
  }

  close() {
    this.ws.close();
  }
}

async function main() {
  const target = await openTarget();
  const cdp = new CDP(target.webSocketDebuggerUrl);
  await cdp.open();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Log.enable');

  async function evaluate(expression, awaitPromise) {
    const result = await cdp.send('Runtime.evaluate', {
      expression,
      awaitPromise: awaitPromise !== false,
      returnByValue: true,
      userGesture: true,
    });
    if (result.exceptionDetails) {
      const details = result.exceptionDetails;
      throw new Error(details.text + ': ' + (details.exception && details.exception.description));
    }
    return result.result.value;
  }

  async function waitFor(expression, label, timeout) {
    const limit = timeout || 8000;
    const started = Date.now();
    let lastError = null;
    while (Date.now() - started < limit) {
      try {
        const value = await evaluate(expression);
        if (value) return value;
      } catch (error) {
        lastError = error;
      }
      await sleep(120);
    }
    throw new Error('Timed out waiting for ' + (label || expression) + (lastError ? ' :: ' + lastError.message : ''));
  }

  async function reloadAndWait() {
    await cdp.send('Page.reload', { ignoreCache: true });
    await waitFor("document.readyState === 'complete'", 'document ready after reload');
    await waitFor("document.querySelectorAll('#menuGrid .donut-card').length === 8", 'menu cards after reload');
    await sleep(350);
  }

  async function navigate(url) {
    await cdp.send('Page.navigate', { url });
    await waitFor("document.readyState === 'complete'", 'document ready');
    await sleep(700);
  }

  async function screenshot(name, fullPage) {
    const params = { format: 'png', fromSurface: true };
    if (fullPage) {
      const metrics = await cdp.send('Page.getLayoutMetrics');
      const size = metrics.cssContentSize || metrics.contentSize;
      params.captureBeyondViewport = true;
      params.clip = { x: 0, y: 0, width: size.width, height: size.height, scale: 1 };
    } else {
      params.captureBeyondViewport = false;
    }
    const shot = await cdp.send('Page.captureScreenshot', params);
    const file = path.join(OUT, name + '.png');
    fs.writeFileSync(file, Buffer.from(shot.data, 'base64'));
    console.log('SHOT ' + file);
    return file;
  }

  async function click(selector) {
    const clicked = await evaluate(
      "(function(){var el=document.querySelector(" +
        JSON.stringify(selector) +
        ");if(!el)return false;el.click();return true;})()"
    );
    if (!clicked) throw new Error('Could not click ' + selector);
    await sleep(180);
  }

  async function setValue(selector, value) {
    return evaluate(
      "(function(){var el=document.querySelector(" +
        JSON.stringify(selector) +
        ");if(!el)return false;el.value=" +
        JSON.stringify(value) +
        ";el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));return true;})()"
    );
  }

  async function injectReceipt() {
    return evaluate(`new Promise(function(resolve){
      var canvas=document.createElement('canvas');
      canvas.width=420;canvas.height=620;
      var ctx=canvas.getContext('2d');
      ctx.fillStyle='#f0f4fa';ctx.fillRect(0,0,420,620);
      ctx.fillStyle='#0a7cf2';ctx.fillRect(0,0,420,150);
      ctx.fillStyle='#ffffff';ctx.font='bold 34px Arial';ctx.fillText('GCash',24,64);
      ctx.font='16px Arial';ctx.fillText('PAYMENT RECEIPT',24,104);
      ctx.fillStyle='#ffffff';ctx.fillRect(20,180,380,380);
      ctx.fillStyle='#0b9b62';ctx.font='bold 28px Arial';ctx.fillText('Payment sent',110,260);
      ctx.fillStyle='#10233e';ctx.font='bold 44px Arial';ctx.fillText('QA receipt',100,330);
      ctx.fillStyle='#7d8a9c';ctx.font='18px Arial';ctx.fillText('Reference: TEST123456',50,400);
      ctx.fillText('Glaze & Co. campus bakery',50,440);
      canvas.toBlob(function(blob){
        var file=new File([blob],'qa-receipt.png',{type:'image/png'});
        var dt=new DataTransfer();dt.items.add(file);
        var input=document.querySelector('#receiptInput');
        input.files=dt.files;
        input.dispatchEvent(new Event('change',{bubbles:true}));
        resolve(true);
      },'image/png');
    })`, true);
  }

  try {
    await navigate(BASE);
    await evaluate("localStorage.clear(); localStorage.setItem('glazeCo.demoSeeded.v1','0'); 'cleared'");
    await reloadAndWait();

    const initial = await evaluate(`(function(){
      return {
        cards: document.querySelectorAll('#menuGrid .donut-card').length,
        filters: document.querySelectorAll('#menuFilters .filter-chip').length,
        badge: document.querySelector('#cartBadge').textContent.trim(),
        siteHidden: document.querySelector('#site').hidden,
        adminHidden: document.querySelector('#adminShell').hidden,
        title: document.title,
        bodyOverflow: getComputedStyle(document.body).overflow
      };
    })()`);
    check('Storefront renders eight donuts', initial.cards === 8, JSON.stringify(initial));
    check('Menu filters render', initial.filters === 5, String(initial.filters));
    check('Cart starts empty', initial.badge === '0', initial.badge);
    check('Storefront is visible on initial load', initial.siteHidden === false && initial.adminHidden === true);
    check('Document has no horizontal overflow', await evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1"));

    await screenshot('01-home', true);

    await click('[data-add-donut="strawberry-sprinkle"]');
    await click('[data-add-donut="strawberry-sprinkle"]');
    const afterDonut = await evaluate(`(function(){
      var cart=JSON.parse(localStorage.getItem('glazeCo.cart.v1')||'[]');
      return {badge:document.querySelector('#cartBadge').textContent.trim(),cart:cart,toast:document.querySelectorAll('#toastRegion .toast').length};
    })()`);
    check('Adding a donut updates the cart badge', afterDonut.badge === '2', afterDonut.badge);
    check('Donut quantity increments instead of duplicating', afterDonut.cart.length === 1 && afterDonut.cart[0].qty === 2, JSON.stringify(afterDonut.cart));
    check('Add-to-cart toast is shown', afterDonut.toast > 0, String(afterDonut.toast));

    await click('[data-box-size="4"]');
    await click('#boxClear');
    const boxCleared = await evaluate("({filled:document.querySelectorAll('#boxGrid .box-slot.is-filled').length,disabled:document.querySelector('#boxAdd').disabled,progress:document.querySelector('#boxProgress').textContent.trim()})");
    check('Clearing the box empties all slots and disables add', boxCleared.filled === 0 && boxCleared.disabled === true, JSON.stringify(boxCleared));
    for (let i = 0; i < 4; i += 1) {
      await click('#boxPicker [data-box-flavor]:not([disabled])');
    }
    const boxFilled = await evaluate("({filled:document.querySelectorAll('#boxGrid .box-slot.is-filled').length,disabled:document.querySelector('#boxAdd').disabled,progress:document.querySelector('#boxProgress').textContent.trim()})");
    check('Box picker fills all four slots and enables add', boxFilled.filled === 4 && boxFilled.disabled === false, JSON.stringify(boxFilled));
    await click('#boxAdd');
    const afterBox = await evaluate(`(function(){
      var cart=JSON.parse(localStorage.getItem('glazeCo.cart.v1')||'[]');
      return {badge:document.querySelector('#cartBadge').textContent.trim(),cart:cart};
    })()`);
    check('Custom box is added to the cart', afterBox.cart.some(function(item){return item.kind==='box' && item.boxSize===4;}), JSON.stringify(afterBox.cart));
    check('Cart badge counts all cart units', afterBox.badge === '3', afterBox.badge);

    await click('[data-open-cart]');
    await waitFor("document.querySelector('#cartDrawer').classList.contains('is-open')", 'cart drawer');
    const cartState = await evaluate("({items:document.querySelectorAll('#cartBody .cart-item').length,subtotal:document.querySelector('#cartFoot .cart-subtotal strong').textContent.trim(),checkout:!!document.querySelector('[data-checkout]')})");
    check('Cart drawer lists both line items', cartState.items === 2, JSON.stringify(cartState));
    check('Cart subtotal is computed correctly', cartState.subtotal === '₱359.00', cartState.subtotal);
    await screenshot('02-cart');

    await click('[data-checkout]');
    await waitFor("document.querySelector('#checkoutModal').classList.contains('is-open')", 'checkout modal');
    const checkoutDefaults = await evaluate(`(function(){
      return {
        date:document.querySelector('#deliveryDate').value,
        time:document.querySelector('#timeSlot').value,
        total:document.querySelector('#summaryTotal').textContent.trim(),
        delivery:document.querySelector('#summaryDelivery').textContent.trim(),
        items:document.querySelectorAll('#checkoutItems .summary-item').length
      };
    })()`);
    check('Checkout pre-fills delivery date and time slot', Boolean(checkoutDefaults.date && checkoutDefaults.time), JSON.stringify(checkoutDefaults));
    check('Checkout totals match the cart', checkoutDefaults.total === '₱388.00' && checkoutDefaults.delivery === '₱29.00', JSON.stringify(checkoutDefaults));
    check('Checkout summary lists cart items', checkoutDefaults.items === 2, String(checkoutDefaults.items));

    await setValue('#fullName', 'QA Tester');
    await setValue('#phone', '0917 123 4567');
    await setValue('#email', 'qa.tester@campus.edu');
    await setValue('#campus', 'Main Campus');
    await setValue('#building', 'Engineering Bldg, Room 101');
    await click('input[name="payment"][value="gcash"]');
    await waitFor("document.querySelector('#gcashPanel').hidden === false", 'GCash panel');
    await setValue('#gcashRef', 'TEST123456');
    await injectReceipt();
    await waitFor("document.querySelector('#receiptPreview').hidden === false && document.querySelector('#receiptThumb').src.indexOf('data:image/jpeg') === 0", 'receipt preview', 10000);
    const receiptState = await evaluate("({preview:!document.querySelector('#receiptPreview').hidden,src:document.querySelector('#receiptThumb').src.slice(0,30),amount:document.querySelector('#gcashAmount').textContent.trim()})");
    check('GCash receipt preview renders', receiptState.preview && receiptState.src === 'data:image/jpeg', JSON.stringify(receiptState));
    check('GCash amount matches order total', receiptState.amount === '₱388.00', receiptState.amount);
    await evaluate("document.querySelector('#checkoutForm').scrollIntoView(); window.scrollTo(0,0)");
    await screenshot('03-checkout-gcash');

    await evaluate("document.querySelector('#checkoutForm').requestSubmit(); true");
    await waitFor("document.querySelector('#confirmationModal').classList.contains('is-open')", 'confirmation modal', 10000);
    const confirmation = await evaluate(`(function(){
      var orders=JSON.parse(localStorage.getItem('glazeCo.orders.v1')||'[]');
      var customer=orders.filter(function(o){return o.source==='customer';});
      return {
        id:document.querySelector('#confirmId').textContent.trim(),
        total:document.querySelector('#confirmTotal').textContent.trim(),
        method:document.querySelector('#confirmMethod').textContent.trim(),
        customerCount:customer.length,
        customer:customer[0]||null,
        cart:JSON.parse(localStorage.getItem('glazeCo.cart.v1')||'[]'),
        badge:document.querySelector('#cartBadge').textContent.trim()
      };
    })()`);
    check('Order confirmation opens', Boolean(confirmation.id), JSON.stringify(confirmation));
    check('Customer order is persisted', confirmation.customerCount === 1 && confirmation.customer.source === 'customer', JSON.stringify(confirmation.customer));
    check('Placed order stores GCash pending payment', confirmation.customer && confirmation.customer.payment.method === 'gcash' && confirmation.customer.payment.status === 'pending' && confirmation.customer.payment.receipt.indexOf('data:image') === 0, confirmation.customer && JSON.stringify(confirmation.customer.payment));
    check('Cart empties after placing an order', confirmation.cart.length === 0 && confirmation.badge === '0', JSON.stringify({ cart: confirmation.cart, badge: confirmation.badge }));
    await screenshot('04-confirmation');

    await click('#confirmTrack');
    await waitFor("document.querySelector('#ordersDrawer').classList.contains('is-open')", 'orders drawer');
    const ordersDrawer = await evaluate("({cards:document.querySelectorAll('#ordersBody .track-card').length,text:document.querySelector('#ordersBody').textContent,status:document.querySelector('#ordersBody .status-chip').textContent.trim()})");
    check('My Orders tracker shows the placed order', ordersDrawer.cards === 1 && ordersDrawer.text.indexOf(confirmation.id) >= 0, JSON.stringify({ cards: ordersDrawer.cards, status: ordersDrawer.status }));
    await screenshot('05-orders');
    await click('#ordersDrawer [data-close]');

    await reloadAndWait();
    const persisted = await evaluate("({orders:JSON.parse(localStorage.getItem('glazeCo.orders.v1')||'[]').filter(function(o){return o.source==='customer';}).length,badge:document.querySelector('#cartBadge').textContent.trim(),nav:document.querySelector('#navOrderCount').textContent.trim(),navHidden:document.querySelector('#navOrderCount').hidden})");
    check('Customer order survives a page reload', persisted.orders === 1, JSON.stringify(persisted));
    check('My Orders nav badge reflects placed order', persisted.nav === '1' && persisted.navHidden === false, JSON.stringify(persisted));

    await evaluate("window.location.hash='#admin'; true");
    await waitFor("document.querySelector('#adminShell').hidden === false && document.querySelector('#adminContent').children.length > 0", 'admin console', 10000);
    await sleep(350);
    const adminOverview = await evaluate(`(function(){
      var orders=JSON.parse(localStorage.getItem('glazeCo.orders.v1')||'[]');
      return {
        siteHidden:document.querySelector('#site').hidden,
        adminHidden:document.querySelector('#adminShell').hidden,
        title:document.title,
        orderCount:orders.length,
        customerOrders:orders.filter(function(o){return o.source==='customer';}).length,
        navOrders:document.querySelector('#adminOrderCount').textContent.trim(),
        navPayments:document.querySelector('#adminPaymentCount').textContent.trim(),
        stats:document.querySelectorAll('.admin-stat-card').length,
        attention:document.querySelectorAll('.attention-item').length,
        heading:document.querySelector('#adminContent h1') ? document.querySelector('#adminContent h1').textContent : ''
      };
    })()`);
    check('Admin route switches away from the storefront', adminOverview.siteHidden === true && adminOverview.adminHidden === false, JSON.stringify(adminOverview));
    check('Admin uses its own page title', adminOverview.title.indexOf('Admin console') === 0, adminOverview.title);
    check('Demo data seeds the admin dashboard', adminOverview.orderCount === 15 && adminOverview.customerOrders === 1, JSON.stringify(adminOverview));
    check('Admin overview renders stats and pending attention items', adminOverview.stats === 4 && adminOverview.attention === 3, JSON.stringify(adminOverview));
    check('Admin nav badges match data', adminOverview.navOrders === '15' && adminOverview.navPayments === '3', JSON.stringify(adminOverview));
    await screenshot('06-admin-overview');

    await click('[data-admin-view="payments"]');
    await waitFor("document.querySelectorAll('.payment-verify-list .verify-card').length === 3", 'three pending payments');
    const paymentsState = await evaluate("({cards:document.querySelectorAll('.payment-verify-list .verify-card').length,summary:document.querySelector('.verify-summary').textContent.replace(/\\s+/g,' ').trim(),receipts:document.querySelectorAll('.verify-receipt img').length})");
    check('Payments view lists all pending GCash receipts', paymentsState.cards === 3 && paymentsState.receipts === 3, JSON.stringify(paymentsState));
    await screenshot('07-admin-payments');

    const customerOrderId = confirmation.id;
    await click('[data-verify-order="' + customerOrderId + '"]');
    await waitFor("JSON.parse(localStorage.getItem('glazeCo.orders.v1')).find(function(o){return o.id==='" + customerOrderId + "';}).payment.status === 'verified'", 'customer payment verification');
    const verified = await evaluate(`(function(){
      var order=JSON.parse(localStorage.getItem('glazeCo.orders.v1')).find(function(o){return o.id==='${customerOrderId}';});
      return {status:order.payment.status,verifiedAt:order.payment.verifiedAt,pendingCards:document.querySelectorAll('.payment-verify-list .verify-card').length,badge:document.querySelector('#adminPaymentCount').textContent.trim(),reviewed:document.querySelector('.verified-list').textContent};
    })()`);
    check('Admin can verify a GCash payment', verified.status === 'verified' && Boolean(verified.verifiedAt), JSON.stringify(verified));
    check('Verification removes the receipt from the pending queue', verified.pendingCards === 2 && verified.badge === '2', JSON.stringify(verified));
    check('Reviewed list records the verification', verified.reviewed.indexOf(customerOrderId) >= 0, verified.reviewed.replace(/\s+/g, ' ').trim());

    await click('[data-manage-order="' + customerOrderId + '"]');
    await waitFor("document.querySelector('#adminOrderModal').classList.contains('is-open')", 'admin order modal');
    const adminModal = await evaluate("({title:document.querySelector('#adminOrderTitle').textContent.trim(),verifiedAlert:!!document.querySelector('.admin-payment-alert.is-success'),advance:!!document.querySelector('.admin-advance'),receipt:!!document.querySelector('.receipt-display img')})");
    check('Admin order detail opens with verified payment and receipt', adminModal.title === customerOrderId && adminModal.verifiedAlert && adminModal.receipt, JSON.stringify(adminModal));
    await screenshot('08-admin-order-modal');

    const statuses = [];
    for (let i = 0; i < 4; i += 1) {
      const currentStatus = await evaluate("JSON.parse(localStorage.getItem('glazeCo.orders.v1')).find(function(o){return o.id==='" + customerOrderId + "';}).status");
      statuses.push(currentStatus);
      const hasAdvance = await evaluate("!!document.querySelector('#adminOrderBody [data-advance-order]')");
      if (!hasAdvance) break;
      await click('#adminOrderBody [data-advance-order]');
      await sleep(230);
    }
    const finalStatus = await evaluate("JSON.parse(localStorage.getItem('glazeCo.orders.v1')).find(function(o){return o.id==='" + customerOrderId + "';}).status");
    statuses.push(finalStatus);
    check('Admin can advance fulfillment through all stages', statuses.join(' > ') === 'pending > confirmed > baking > out-for-delivery > delivered', statuses.join(' > '));
    await click('#adminOrderModal [data-close]');

    await click('[data-admin-view="orders"]');
    await waitFor("document.querySelectorAll('#adminOrdersList tbody tr').length > 0", 'orders table');
    await setValue('[data-admin-search]', 'QA Tester');
    await sleep(250);
    const orderSearch = await evaluate("({rows:document.querySelectorAll('#adminOrdersList tbody tr').length,text:document.querySelector('#adminOrdersList tbody').textContent.replace(/\\s+/g,' ').trim()})");
    check('Admin order search filters to the customer order', orderSearch.rows === 1 && orderSearch.text.indexOf(customerOrderId) >= 0, JSON.stringify(orderSearch));
    await evaluate("document.querySelector('[data-admin-search]').value=''; document.querySelector('[data-admin-search]').dispatchEvent(new Event('input',{bubbles:true})); true");
    await screenshot('09-admin-orders');

    await click('[data-admin-view="campus"]');
    await waitFor("document.querySelectorAll('.campus-chart-row').length === 3", 'campus chart');
    const campusState = await evaluate("({rows:document.querySelectorAll('.campus-chart-row').length,summary:document.querySelectorAll('.campus-summary-item').length,table:document.querySelectorAll('.campus-table-card tbody tr').length,range:document.querySelector('.campus-range-tab.is-active').textContent.trim(),report:document.querySelector('.report-top-items').textContent.replace(/\\s+/g,' ').trim()})");
    check('Campus sales view renders all campuses', campusState.rows === 3 && campusState.summary === 3 && campusState.table === 3, JSON.stringify(campusState));
    check('Campus report defaults to this week', campusState.range === 'This week', campusState.range);
    check('Campus report includes top donuts', campusState.report.indexOf('sold') >= 0, campusState.report.slice(0, 120));
    await screenshot('10-admin-campus');

    await cdp.send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
    await evaluate("window.location.hash='#top'; true");
    await waitFor("document.querySelector('#site').hidden === false", 'storefront after mobile navigation');
    await sleep(500);
    const mobileHome = await evaluate("({width:window.innerWidth,overflow:document.documentElement.scrollWidth,menuHidden:document.querySelector('#mobileNav').hidden,navButton:!!document.querySelector('#mobileMenuBtn'),miniBar:getComputedStyle(document.querySelector('#mobileMenuBtn')).display})");
    check('Mobile storefront has no horizontal overflow', mobileHome.width === 390 && mobileHome.overflow <= 391, JSON.stringify(mobileHome));
    await evaluate("window.scrollTo(0,0)");
    await screenshot('11-mobile-home');
    await click('#mobileMenuBtn');
    const mobileNavOpen = await evaluate("document.querySelector('#mobileNav').hidden === false && document.querySelector('#mobileMenuBtn').getAttribute('aria-expanded') === 'true'");
    check('Mobile menu toggles open', mobileNavOpen);
    await screenshot('12-mobile-menu');
    await click('#mobileMenuBtn');
    await evaluate("window.location.hash='#admin'; true");
    await waitFor("document.querySelector('#adminShell').hidden === false && document.querySelector('#adminContent').children.length > 0", 'mobile admin');
    await sleep(400);
    const mobileAdmin = await evaluate("({overflow:document.documentElement.scrollWidth,width:window.innerWidth,sidebar:!!document.querySelector('.admin-sidebar'),stats:document.querySelectorAll('.admin-stat-card').length})");
    check('Mobile admin has no horizontal overflow', mobileAdmin.overflow <= 391, JSON.stringify(mobileAdmin));
    await screenshot('13-mobile-admin');

    check('No uncaught JavaScript exceptions occurred', exceptions.length === 0, JSON.stringify(exceptions));
    const severeLogs = logEntries.filter(function (entry) {
      return entry.level === 'error';
    });
    check('No browser error logs occurred', severeLogs.length === 0, JSON.stringify(severeLogs));
    const consoleErrors = consoleMessages.filter(function (entry) {
      return entry.type === 'error';
    });
    check('No console errors occurred', consoleErrors.length === 0, JSON.stringify(consoleErrors));
  } catch (error) {
    check('QA flow completed without interruption', false, error.stack || error.message);
  } finally {
    const report = {
      generatedAt: new Date().toISOString(),
      outDir: OUT,
      checks,
      failures,
      exceptions,
      consoleMessages,
      logEntries,
    };
    fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify(report, null, 2));
    console.log('');
    console.log('SUMMARY ' + (checks.length - failures.length) + '/' + checks.length + ' checks passed');
    if (failures.length) console.log('FAILURES\n' + failures.join('\n'));
    if (exceptions.length) console.log('EXCEPTIONS\n' + JSON.stringify(exceptions, null, 2));
    console.log('REPORT ' + path.join(OUT, 'report.json'));
    cdp.close();
    await fetch(CDP_BASE + '/json/close/' + target.id);
  }
}

main().catch(function (error) {
  console.error('FATAL', error);
  process.exitCode = 1;
});

